"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

import { supabaseClient } from "@/lib/supabase-client";

export function LoginButton() {
	const router = useRouter();
	const [loading, setLoading] = useState(false);

	async function handleSignIn() {
		setLoading(true);
		const { error } = await supabaseClient.auth.signInWithOAuth({
			provider: "google",
			options: {
				redirectTo: `${window.location.origin}/auth/callback`,
			},
		});
		if (error) {
			setLoading(false);
			console.error("Sign-in failed", error);
			router.refresh();
		}
	}

	return (
		<button
			type="button"
			onClick={handleSignIn}
			disabled={loading}
			className="rounded-md bg-foreground px-4 py-2 text-sm font-medium text-background transition-opacity hover:opacity-80 disabled:opacity-50"
		>
			{loading ? "Redirecting…" : "Continue with Google"}
		</button>
	);
}

import { Suspense } from "react";

import { LoginButton } from "@/components/login-button";

export default function LoginPage() {
	return (
		<main className="container mx-auto flex h-full max-w-md flex-col items-center justify-center gap-6 px-4">
			<div className="text-center">
				<h1 className="text-2xl font-semibold">Sign in to Aevryn</h1>
				<p className="mt-2 text-sm text-muted-foreground">
					Google-only login. Your workspace is created automatically on
					first sign-in.
				</p>
			</div>
			<Suspense>
				<LoginButton />
			</Suspense>
		</main>
	);
