import { sql, type SQL } from "drizzle-orm";

export const uid = sql`auth.uid()`;

export const isMemberOf = (workspaceId: unknown): SQL =>
	sql`exists (select 1 from "workspace_members" wm where wm."workspace_id" = ${workspaceId} and wm."user_id" = auth.uid())`;

export const isEditorOf = (workspaceId: unknown): SQL =>
	sql`exists (select 1 from "workspace_members" wm where wm."workspace_id" = ${workspaceId} and wm."user_id" = auth.uid() and wm."role" in ('owner', 'editor'))`;

// Owner-check avoids any self-reference into workspace_members —
// used by workspace_members' OWN policies.
export const ownsWorkspace = (workspaceId: unknown): SQL =>
	sql`exists (select 1 from "workspaces" w where w."id" = ${workspaceId} and w."created_by" = auth.uid())`;

export const workflowVisible = (workflowId: unknown): SQL =>
	sql`exists (select 1 from "workflows" w where w."id" = ${workflowId} and (w."user_id" = auth.uid() or ${isMemberOf(sql`w."workspace_id"`)}))`;

export const workflowEditable = (workflowId: unknown): SQL =>
	sql`exists (select 1 from "workflows" w where w."id" = ${workflowId} and (w."user_id" = auth.uid() or ${isEditorOf(sql`w."workspace_id"`)}))`;

export const workflowOwned = (workflowId: unknown): SQL =>
	sql`exists (select 1 from "workflows" w where w."id" = ${workflowId} and w."user_id" = auth.uid())`;

// plan steps ride on plans → workflows; plans policies are not
// self-referential, so the chain is recursion-free.
export const stepViaVisibleWorkflow = (planId: unknown): SQL =>
	sql`exists (select 1 from "plans" p join "workflows" w on w."id" = p."workflow_id" where p."id" = ${planId} and (w."user_id" = auth.uid() or ${isMemberOf(sql`w."workspace_id"`)}))`;

export const stepViaEditableWorkflow = (planId: unknown): SQL =>
	sql`exists (select 1 from "plans" p join "workflows" w on w."id" = p."workflow_id" where p."id" = ${planId} and (w."user_id" = auth.uid() or ${isEditorOf(sql`w."workspace_id"`)}))`;

export const stepViaOwnedWorkflow = (planId: unknown): SQL =>
	sql`exists (select 1 from "plans" p join "workflows" w on w."id" = p."workflow_id" where p."id" = ${planId} and w."user_id" = auth.uid())`;

import { sql } from "drizzle-orm";
import { boolean, index, pgPolicy, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { authenticatedRole } from "drizzle-orm/supabase";

import { groups } from "./group";
import { isEditorOf, isMemberOf } from "./policies";
import { workspaces } from "./workspace";

export const threads = pgTable(
	"threads",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		groupId: text("group_id").references(() => groups.id, {
			onDelete: "set null",
		}),
		userId: uuid("user_id").notNull(),
		title: text("title").notNull().default(""),
		deletedAt: timestamp("deleted_at", { withTimezone: true }),
		shareEnabled: boolean("share_enabled").notNull().default(false),
		boundWorkflowId: text("bound_workflow_id"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
		lastMessageAt: timestamp("last_message_at", { withTimezone: true }),
	},
	(table) => [
		index("threads_user_workspace_last_msg_idx").on(
			table.userId,
			table.workspaceId,
			table.lastMessageAt,
		),
		index("threads_group_idx").on(table.groupId),
		pgPolicy("threads_select", {
			for: "select",
			to: authenticatedRole,
			using: sql`${table.userId} = auth.uid() or ${isMemberOf(table.workspaceId)} or exists (select 1 from "thread_shares" ts where ts."thread_id" = ${table.id} and ts."user_id" = auth.uid())`,
		}),
		pgPolicy("threads_insert", {
			for: "insert",
			to: authenticatedRole,
			withCheck: sql`${table.userId} = auth.uid() and ${isEditorOf(table.workspaceId)}`,
		}),
		pgPolicy("threads_update", {
			for: "update",
			to: authenticatedRole,
			using: sql`${table.userId} = auth.uid() or ${isEditorOf(table.workspaceId)}`,
		}),
		pgPolicy("threads_delete", {
			for: "delete",
			to: authenticatedRole,
			using: sql`${table.userId} = auth.uid()`,
		}),
	],
).enableRLS();

export type Thread = typeof threads.$inferSelect;
export type NewThread = typeof threads.$inferInsert;

import { pgPolicy, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { authenticatedRole } from "drizzle-orm/supabase";

import { planStatusEnum } from "./enums";
import { workflowEditable, workflowOwned, workflowVisible } from "./policies";
import { workflows } from "./workflow";

export const plans = pgTable(
	"plans",
	{
		id: text("id").primaryKey(),
		workflowId: text("workflow_id")
			.notNull()
			.unique()
			.references(() => workflows.id, { onDelete: "cascade" }),
		title: text("title").notNull(),
		objective: text("objective"),
		summary: text("summary"),
		status: planStatusEnum("status").notNull().default("draft"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		pgPolicy("plans_select", {
			for: "select",
			to: authenticatedRole,
			using: workflowVisible(table.workflowId),
		}),
		pgPolicy("plans_insert", {
			for: "insert",
			to: authenticatedRole,
			withCheck: workflowEditable(table.workflowId),
		}),
		pgPolicy("plans_update", {
			for: "update",
			to: authenticatedRole,
			using: workflowEditable(table.workflowId),
		}),
		pgPolicy("plans_delete", {
			for: "delete",
			to: authenticatedRole,
			using: workflowOwned(table.workflowId),
		}),
	],
).enableRLS();

export type Plan = typeof plans.$inferSelect;
export type NewPlan = typeof plans.$inferInsert;

import { sql } from "drizzle-orm";
import { pgPolicy, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { authenticatedRole } from "drizzle-orm/supabase";

import { roleEnum } from "./enums";
import { ownsWorkspace } from "./policies";
import { workspaces } from "./workspace";

export const workspaceMembers = pgTable(
	"workspace_members",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		role: roleEnum("role").notNull().default("viewer"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		uniqueIndex("workspace_members_workspace_user_idx").on(
			table.workspaceId,
			table.userId,
		),
		pgPolicy("workspace_members_select", {
			for: "select",
			to: authenticatedRole,
			using: sql`${table.userId} = auth.uid()`,
		}),
		pgPolicy("workspace_members_insert", {
			for: "insert",
			to: authenticatedRole,
			withCheck: ownsWorkspace(table.workspaceId),
		}),
		pgPolicy("workspace_members_update", {
			for: "update",
			to: authenticatedRole,
			using: ownsWorkspace(table.workspaceId),
			withCheck: ownsWorkspace(table.workspaceId),
		}),
		pgPolicy("workspace_members_delete", {
			for: "delete",
			to: authenticatedRole,
			using: sql`${ownsWorkspace(table.workspaceId)} and ${table.role} != 'owner'`,
		}),
	],
).enableRLS();

export type WorkspaceMember = typeof workspaceMembers.$inferSelect;
export type NewWorkspaceMember = typeof workspaceMembers.$inferInsert;

