ALTER POLICY "workspace_members_select" ON "workspace_members" TO authenticated USING ("workspace_members"."user_id" = auth.uid());

ALTER POLICY "workspace_members_insert" ON "workspace_members" TO authenticated WITH CHECK (exists (select 1 from "workspaces" w where w."id" = "workspace_members"."workspace_id" and w."created_by" = auth.uid()));

ALTER POLICY "workspace_members_update" ON "workspace_members" TO authenticated USING (exists (select 1 from "workspaces" w where w."id" = "workspace_members"."workspace_id" and w."created_by" = auth.uid())) WITH CHECK (exists (select 1 from "workspaces" w where w."id" = "workspace_members"."workspace_id" and w."created_by" = auth.uid()));

ALTER POLICY "workspace_members_delete" ON "workspace_members" TO authenticated USING (exists (select 1 from "workspaces" w where w."id" = "workspace_members"."workspace_id" and w."created_by" = auth.uid()) and "workspace_members"."role" != 'owner');

