	constructor(private readonly client: Db = db) {}

	private scope() {
		return this.client;
	}

	async create(input: CreateThreadInput): Promise<Thread> {
		const [row] = await this.scope()
			.insert(threads)
			.values({
				id: ids.thread(),
				workspaceId: input.workspaceId,
				userId: input.userId,
				groupId: input.groupId ?? null,
				title: input.title ?? "",
			})
			.returning();
