): AgentStateValue {
	const next = { ...(current ?? {}) };
	for (const key of ["phase", "context"] as const) {
		if (patch[key] !== undefined) {
			next[key] = patch[key];
		}
	}
	next.data = {
		...(current?.data ?? {}),
		...(patch.data ?? {}),
	};
	return next;
}

