import { computeNextRun, ScheduleService } from "@aevryn/workflow";
import { z } from "zod";

import type { Capability } from "../capability";
import { toCapabilityFailure } from "../errors";

const createScheduleInputSchema = z
	.object({
		cron: z
			.string()
			.min(1)
			.max(100)
			.describe(
				"Standard 5-field cron expression (minute hour day month weekday), e.g. '0 9 * * 1' for weekly Monday 9am.",
			)
			.optional(),
		intervalSeconds: z
			.number()
			.int()
			.positive()
			.max(86_400)
			.describe("Fixed interval in seconds between runs (max 24 hours).")
			.optional(),
		prompt: z
			.string()
			.min(1)
			.max(2000)
			.optional()
			.describe(
				"Specific instruction to run at each fire. Defaults to the current objective.",
			),
		startAt: z
			.string()
			.datetime({ offset: true })
			.optional()
			.describe(
				"Optional first run time as an ISO-8601 timestamp (e.g. '2026-09-15T09:00:00Z'); defaults to now.",
			),
	})
	.superRefine((value, ctx) => {
		if (!value.cron && !value.intervalSeconds) {
			ctx.addIssue({
				code: "custom",
				path: ["cron"],
				message: "Provide either cron or intervalSeconds.",
			});
		}
	});

export function createScheduleCapability(context: {
	threadId: string;
	workspaceId: string;
	userId: string;
}): Capability {
	const service = new ScheduleService();
	return {
		name: "createSchedule",
		description:
			"Create a recurring schedule on this thread. The agent runs " +
			"again automatically at each scheduled time (cron expression or fixed " +
			"interval), letting you monitor something over time and report back. " +
			"Use this for 'check every ...', 'monitor ... until ...', or 'notify me " +
			"when ...' objectives instead of finishing immediately.",
		inputSchema: createScheduleInputSchema,
		async execute(input) {
			const parsed = createScheduleInputSchema.safeParse(input);
			if (!parsed.success) {
				return {
					ok: false,
					error: {
						code: "INVALID_CAPABILITY_INPUT",
						message: parsed.error.message,
						failureClass: "fatal",
						retryable: false,
					},
				};
			}
			try {
				const startDate = parsed.data.startAt
					? new Date(parsed.data.startAt)
					: undefined;
				const nextRunAt = computeNextRun(
					parsed.data.cron,
					parsed.data.intervalSeconds,
					startDate,
				);
				const schedule = await service.upsert({
					workspaceId: context.workspaceId,
					threadId: context.threadId,
					userId: context.userId,
					cron: parsed.data.cron,
					intervalSeconds: parsed.data.intervalSeconds,
					startAt: startDate,
					config: { prompt: parsed.data.prompt },
				});
				return {
					ok: true,
					data: {
						scheduleId: schedule.id,
						cron: schedule.cron,
						intervalSeconds: schedule.intervalSeconds,
						prompt: parsed.data.prompt,
						nextRunAt: nextRunAt.toISOString(),
					},
				};
			} catch (error) {
				return toCapabilityFailure(error, 0);
			}
		},
	};
}

import {
	computeNextRun,
	NotificationService,
	RunService,
	ScheduleService,
	ThreadService,
} from "@aevryn/workflow";
import { NonRetriableError } from "inngest";

import { inngest } from "../client";
import { threadRunEvent } from "../events";

const scheduleService = new ScheduleService();
const runService = new RunService();
const threadService = new ThreadService();
const notificationService = new NotificationService();

interface FireOutcome {
	scheduleId: string;
	runId?: string;
	skipped?: string;
}

interface WakeOutcome {
	runId: string;
	skipped?: string;
}

export const scheduleTick = inngest.createFunction(
	{
		id: "schedule-tick",
		retries: 2,
	},
	async ({ step }) => {
		const now = new Date();
		const due = await step.run("find-due-work", async () => {
			return {
				schedules: await scheduleService.listDue(now),
				sleeping: await runService.listSleepingDue(now),
			};
		});

		const fired: FireOutcome[] = [];
		for (const schedule of due.schedules) {
			const outcome = await step.run("fire-schedule", async () => {
				const thread = await threadService.findById(schedule.threadId);
				if (!thread) {
					await scheduleService.setEnabled(schedule.id, false);
					return {
						scheduleId: schedule.id,
						skipped: "thread unavailable",
					} satisfies FireOutcome;
				}
				const prompt = (
					((schedule.config ?? {}) as { prompt?: string }).prompt ??
					thread.title
				).slice(0, 2000);
				const { id: runId } = await runService.create({
					threadId: thread.id,
					userId: schedule.userId,
					trigger: "schedule",
					workflowId: thread.boundWorkflowId ?? undefined,
					promptSnapshot: { prompt },
				});
				await inngest.send({
					name: threadRunEvent,
					data: {
						runId,
						threadId: thread.id,
						prompt,
					},
				});
				const nextRunAt = computeNextRun(
					schedule.cron ?? undefined,
					schedule.intervalSeconds ?? undefined,
				);
				await scheduleService.markRan(schedule.id, nextRunAt, runId);
				try {
					await notificationService.create({
						userId: schedule.userId,
						workspaceId: schedule.workspaceId,
						threadId: thread.id,
						type: "run",
						title: "Scheduled run started",
						body: JSON.stringify({ prompt, runId }),
					});
				} catch {
					// Best-effort.
				}
				return {
					scheduleId: schedule.id,
					runId,
				} satisfies FireOutcome;
			});
			fired.push(outcome);
		}

		const woken: WakeOutcome[] = [];
		for (const run of due.sleeping) {
			const outcome = await step.run("wake-sleeping", async () => {
				const thread = await threadService.findById(run.threadId);
				if (!thread) {
					return {
						runId: run.id,
						skipped: "thread unavailable",
					} satisfies WakeOutcome;
				}
				await runService.resumeTriggeredBy(run.id);
				const prompt = (
					((run.promptSnapshot ?? {}) as { prompt?: string }).prompt ??
					thread.title
				).slice(0, 2000);
				await inngest.send({
					name: threadRunEvent,
					data: {
						runId: run.id,
						threadId: thread.id,
						prompt,
					},
				});
				return {
					runId: run.id,
				} satisfies WakeOutcome;
			});
			woken.push(outcome);
		}

		return {
			firedSchedules: fired.length,
			wokenExecutions: woken.length,
			fired,
			woken,
		};
	},
);

