304		}): Promise<RunActivity | undefined> {
305			const existing = await this.scope().query.runActivities.findFirst({
306				where: and(
307					eq(runActivities.runId, runId),
308					eq(runActivities.stepLabel, "recovery"),
309					sql`${runActivities.detail}->>'attempt' = ${String(input.attempt)}`,
310				),
311			});
312			if (existing) {
313				return undefined;
314			}
315			return this.createActivity({
316				runId,
317				type: "system",
318				status: "complete",
319				stepLabel: "recovery",
320				title: `Recovery attempt ${input.attempt}`,
321				detail: {
322					attempt: input.attempt,
323					failureClass: input.failureClass,
324					failureCode: input.failureCode ?? null,
325					strategy: input.strategy,
326					result: input.result,
327					...(input.detail ?? {}),
328				},
329			});
