import { z } from "zod";

/**
 * Single source of truth for the live-chat tool inputs. Both the server route
 * (tools) and the client (composer affordances) import from here, so the
 * schemas can never drift apart.
 */
export const chatToolSchemas = {
	listCapabilities: z.object({}).strict(),

	askQuestion: z
		.object({
			question: z.string().min(1).max(500),
			context: z.string().max(1000).optional(),
		})
		.strict(),

	showPlan: z.object({}).strict(),

	editPlan: z
		.object({
			action: z.enum(["add_step", "update_step", "set_status", "update_title"]),
			stepId: z.string().min(1).optional(),
			title: z.string().max(200).optional(),
			description: z.string().max(2000).optional(),
			status: z.enum(["pending", "active", "completed", "skipped"]).optional(),
		})
		.strict(),

	bindWorkflow: z
		.object({
			title: z.string().min(1).max(200),
			objective: z.string().max(2000).optional(),
			steps: z
				.array(
					z.object({
						title: z.string().min(1).max(200),
						description: z.string().max(2000).optional(),
					}),
				)
				.max(50),
		})
		.strict(),

	storeMemory: z
		.object({
			text: z.string().min(1).max(4000),
			category: z.enum(["working", "episodic", "semantic", "procedural"]).optional(),
		})
		.strict(),

	searchMemory: z
		.object({
			query: z.string().min(1).max(500),
			limit: z.number().int().min(1).max(20).optional(),
			threadScope: z.boolean().optional(),
		})
		.strict(),

	httpRequest: z
		.object({
			url: z.string().url().min(1).max(2000),
			method: z.enum(["GET", "POST", "PUT", "PATCH", "DELETE"]).default("GET"),
			headers: z.record(z.string(), z.string()).optional(),
			body: z.string().max(5000).optional(),
		})
		.strict(),

	delegateAgenticWork: z
		.object({
			objective: z.string().min(1).max(2000),
			instructions: z.string().max(2000).optional(),
		})
		.strict(),
} as const;

export type ChatToolName = keyof typeof chatToolSchemas;

export const CHAT_TOOL_NAMES = Object.keys(chatToolSchemas) as ChatToolName[];

/**
 * System prompt for the live chat route. Kept adjacent to the durable-run
 * decision instructions so the chat model uses the same vocabulary about
 * workflows, plans, and the user's workspace.
 */
export const CHAT_SYSTEM_PROMPT = `You are Aevryn, a work agent embedded in the user's chat. You respond to the user in this thread, use your tools to look things up and act on their workspace, and keep answers concise and plain-text.

Tool usage rules:
- Prefer tools over speculation: read the bound plan, check memory, and act through the agents/tools. Do not invent results.
- When a plan is bound to this thread, align your work with its steps and mention progress.
- When you cannot act immediately (a user decision is needed, or the work is long-running), say what you need instead of guessing.
- Long-running or multi-step objectives are delegated to the durable worker via delegateAgenticWork — use it when the objective needs several steps, waiting, webhooks, or scheduled checks that a direct reply cannot complete.
- Never echo secrets, API keys, or credentials. Keep httpRequest payloads to what the user asked.

Plan behavior:
- Use showPlan to inspect the thread's plan, editPlan to update it, bindWorkflow to establish a new workflow+plan from the user's objective.
- When you create a plan with bindWorkflow, cover the objective in concrete, ordered steps.

Memory:
- storeMemory records a durable fact/preference for this user. Use it for choices the user states ("always...", "never...", "I prefer...").
- searchMemory recalls what you or previous runs already know. Check it before re-doing work.

Finishing:
- End with a plain-text answer for the user. If you delegated to the durable worker, tell them it is running and what you asked it to do, and that progress appears as activities in the thread.
`;

export interface ChatContext {
	workflowId?: string;
	autoApprove: boolean;
	maxOutputTokens: number;
	modelName: string;
}

/**
 * Static context block appended to the base prompt for a given request:
 * what the thread is bound to, current approval posture, and model caps.
 */
export function buildChatSystemPrompt(context: ChatContext): string {
	const parts: string[] = [CHAT_SYSTEM_PROMPT];

	parts.push(
		[
			"Current session:",
			`- Bound workflow: ${context.workflowId ?? "none (no plan bound yet)"}`,
			`- Auto-approve: ${context.autoApprove ? "ON — you may act without asking; still inform the user of consequential actions." : "OFF — ask the user before consequential external actions."}`,
			`- Max output tokens: ${context.maxOutputTokens}`,
			`- Model: ${context.modelName}`,
		].join("\n"),
	);

	return parts.join("\n\n");
}

import { tool, type Tool } from "ai";
import { db, ids, workflows, type Workflow as WorkflowRow } from "@aevryn/db";
import type {
	MemoryService,
	PlanService,
	RunService,
	ThreadService,
} from "@aevryn/workflow";
import { z } from "zod";

import { chatToolSchemas, CHAT_TOOL_NAMES } from "./schemas";

export interface ChatToolServices {
	plan: PlanService;
	run: RunService;
	thread: ThreadService;
	memory: MemoryService;
}

export interface ChatToolActivity {
	tool: string;
	input: unknown;
	ok: boolean;
	output?: unknown;
	error?: { code: string; message: string };
	durationMs?: number;
}

export interface ChatToolContext {
	userId: string;
	workspaceId: string;
	threadId: string;
	workflowId?: string;
	autoApprove: boolean;
	services: ChatToolServices;
	onDelegateWork(input: {
		objective: string;
		instructions?: string;
	}): Promise<{ runId: string }>;
	onToolActivity?(activity: ChatToolActivity): Promise<void> | void;
}

const HTTP_RESPONSE_CAP = 200_000;
const HTTP_TIMEOUT_MS = 15_000;

function formatPlan(
	plan: { id: string; title: string; objective: string | null; status: string },
	steps: { id: string; position: number; title: string; status: string }[],
) {
	return {
		planId: plan.id,
		title: plan.title,
		objective: plan.objective ?? "",
		status: plan.status,
		steps: steps.map((s) => ({
			id: s.id,
			position: s.position,
			title: s.title,
			status: s.status,
		})),
	};
}

export function createChatTools(ctx: ChatToolContext): Record<string, Tool> {
	const services = ctx.services;

	async function act<T>(
		name: string,
		input: unknown,
		fn: () => Promise<T>,
	): Promise<T> {
		const startedAt = Date.now();
		try {
			const output = await fn();
			await ctx.onToolActivity?.({
				tool: name,
				input,
				ok: true,
				output,
				durationMs: Date.now() - startedAt,
			});
			return output;
		} catch (error) {
			const message =
				error instanceof Error ? error.message : "Unknown tool error";
			await ctx.onToolActivity?.({
				tool: name,
				input,
				ok: false,
				error: { code: (error as { code?: string })?.code ?? "TOOL_ERROR", message },
				durationMs: Date.now() - startedAt,
			});
			throw error;
		}
	}

	const boundWorkflow = async (): Promise<{
		ok: boolean;
		plan: ReturnType<typeof formatPlan> | null;
	}> => {
		if (!ctx.workflowId) {
			return { ok: false, plan: null };
		}
		const plan = await services.plan.getPlanWithSteps(ctx.workflowId);
		if (!plan) {
			return { ok: true, plan: null };
		}
		return { ok: true, plan: formatPlan(plan.plan, plan.steps) };
	};

	return {
		listCapabilities: tool({
			name: "listCapabilities",
			description:
				"List every tool available in this chat session and a one-line description of each. Use it when deciding what you can do for the user.",
			inputSchema: chatToolSchemas.listCapabilities,
			execute: async () => {
				return {
					tools: [
						{ name: "listCapabilities", description: "List available chat tools." },
						{ name: "askQuestion", description: "Ask the user a question and pause for their reply." },
						{ name: "showPlan", description: "Show the plan bound to this thread." },
						{ name: "editPlan", description: "Add/update steps or change the bound plan's status." },
						{ name: "bindWorkflow", description: "Create a workflow + plan from the user's objective and bind it to this thread." },
						{ name: "storeMemory", description: "Store a durable user fact or preference." },
						{ name: "searchMemory", description: "Recall stored facts/preferences for this user." },
						{ name: "httpRequest", description: "Issue a raw HTTP request (GET/POST/PUT/PATCH/DELETE) with a capped response." },
						{ name: "delegateAgenticWork", description: "Hand a multi-step objective to the durable worker; runs asynchronously in this thread." },
					],
				};
			},
		}),

		askQuestion: tool({
			name: "askQuestion",
			description:
				"Surface a question to the user that must be answered before work can continue. Call this, then ask the question in plain text and end your turn; the user's next message is the answer.",
			inputSchema: chatToolSchemas.askQuestion,
			execute: async (input) => {
				return act("askQuestion", input, async () => ({
					status: "pending_user_input",
					guidance:
						"Ask the user the question in plain text in your reply, then end your turn. Continue once they answer.",
				}));
			},
		}),

		showPlan: tool({
			name: "showPlan",
			description:
				"Show the workflow plan currently bound to this thread. Use before proposing work so you align with the existing plan.",
			inputSchema: chatToolSchemas.showPlan,
			execute: async () => {
				return act("showPlan", {}, async () => {
					const current = await boundWorkflow();
					if (!current.ok) {
						return { bound: false, message: "No workflow is bound to this thread yet. Use bindWorkflow to create one." };
					}
					if (!current.plan) {
						return { bound: true, plan: null, message: "The thread has a bound workflow but no plan yet." };
					}
					return { bound: true, plan: current.plan };
				});
			},
		}),

		editPlan: tool({
			name: "editPlan",
			description:
				"Modify the plan bound to this thread: add a step, update a step, change a step's status, or rename the plan. Returns the updated plan.",
			inputSchema: chatToolSchemas.editPlan,
			execute: async (input) => {
				return act("editPlan", input, async () => {
					if (!ctx.workflowId) {
						return { ok: false, error: "No workflow is bound to this thread. Use bindWorkflow first." };
					}
					const previous = await boundWorkflow();
					const plan = previous.plan;
					if (!plan) {
						return { ok: false, error: "No plan exists for the bound workflow." };
					}
					if (input.action === "update_title") {
						if (!input.title) {
							return { ok: false, error: "title is required for update_title." };
						}
						await services.plan.update(plan.planId, { title: input.title });
					} else if (input.action === "add_step") {
						if (!input.title) {
							return { ok: false, error: "title is required for add_step." };
						}
						await services.plan.addStep({
							planId: plan.planId,
							title: input.title,
							description: input.description,
						});
					} else if (input.action === "set_status") {
						if (!input.stepId || !input.status) {
							return { ok: false, error: "stepId and status are required for set_status." };
						}
