			inputSchema: chatToolSchemas.bindWorkflow,
			execute: async (input) => {
				return act("bindWorkflow", input, async () => {
					if (ctx.workflowId) {
						const existing = await boundWorkflow();
						return {
							ok: true,
							alreadyBound: true,
							workflowId: ctx.workflowId,
							plan: existing.plan,
						};
					}
					const [wf] = await db
						.insert(workflows)
						.values({
							id: ids.workflow(),
							threadId: ctx.threadId,
							workspaceId: ctx.workspaceId,
							userId: ctx.userId,
							title: input.title,
							description: input.objective ?? null,
							autoApprove: ctx.autoApprove,
						})
						.returning();
					if (!wf) {
						return { ok: false, error: "Could not create workflow." };
					}
					const plan = await services.plan.create({
						workflowId: wf.id,
						title: input.title,
						objective: input.objective,
					});
					for (const [i, step] of input.steps.entries()) {
						await services.plan.addStep({
							planId: plan.id,
							title: step.title,
							description: step.description,
							position: i,
						});
					}
					await services.thread.bindWorkflow(ctx.threadId, wf.id);
					const steps = await services.plan.listSteps(plan.id);
					return {
						ok: true,
						alreadyBound: false,
						workflowId: wf.id,
						plan: formatPlan(
							{
								id: plan.id,
								title: plan.title,
								objective: plan.objective,
								status: plan.status,
							},
							steps,
						),
					};
				});
			},
		}),

		storeMemory: tool({
			name: "storeMemory",
			description:
				"Persist a durable fact or user preference (or a procedural note about how work should be done). Returns the stored memory id.",
			inputSchema: chatToolSchemas.storeMemory,
			execute: async (input) => {
				return act("storeMemory", input, async () => {
					const result = await services.memory.store({
						userId: ctx.userId,
						text: input.text,
						category: input.category,
						workspaceId: ctx.workspaceId,
						threadId: ctx.threadId,
					});
					return result;
				});
			},
		}),

		searchMemory: tool({
			name: "searchMemory",
			description:
				"Search the user's stored memory (facts, preferences, procedures). Set threadScope to true to restrict recall to this thread's memories.",
			inputSchema: chatToolSchemas.searchMemory,
			execute: async (input) => {
				return act("searchMemory", input, async () => {
					const entries = await services.memory.search({
						userId: ctx.userId,
						query: input.query,
						limit: input.limit ?? 8,
						workspaceId: ctx.workspaceId,
