11		if (header) {
12			for (const part of header.split(";")) {
13				const eq = part.indexOf("=");
14				if (eq <= 0) continue;
15				const name = part.slice(0, eq).trim();
16				const value = decodeURIComponent(part.slice(eq + 1).trim());
17				if (name) cookies.set(name, value);
18			}
19		}
20		return {
21			getAll() {
22				return Array.from(cookies, ([name, value]) => ({ name, value }));
23			},
24			setAll() {
25				// Read-only: token refresh handled by the proxy.
26			},
27		};
28	}
