38	/**
39	 * Durable wait/resume tokens — the blessed home for the `wait` decision
40	 * (`whk_` ULID, SCHEMA.md §19). The plaintext token is handed to the user,
41	 * never persisted; only its SHA-256 hash is stored (unauthenticated route
42	 * auths through the token alone). One run may mint several hooks.
43	 */
44	export class WebhookHookService {
45		constructor(private readonly client: Db = db) {}
46	
47		private scope(): Db {
48			return this.client;
49		}
50	
51		/**
52		 * Mint a hook and flip the run to `waiting`. Returns the raw token + the
53		 * public URL to hand back to the model, which the user POSTs to when the
54		 * external event happens.
55		 */
56		async mint(input: MintWebhookInput): Promise<{ token: string; url: string }> {
57			const token = randomBytes(24).toString("base64url");
58			const tokenHash = createHash("sha256").update(token).digest("hex");
59			const expiresAt = input.expiresInSeconds
60				? new Date(Date.now() + input.expiresInSeconds * 1000)
61				: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
62			await this.scope().insert(webhookHooks).values({
63				id: ids.webhookHook(),
64				runId: input.runId,
65				workspaceId: input.workspaceId,
66				threadId: input.threadId,
67				userId: input.userId,
68				tokenHash,
69				status: "active",
70				expiresAt,
71				consumePayload: { instruction: input.instruction } as never,
72			});
73			return {
74				token,
75				url: `${env.WEBHOOK_BASE_URL}/api/v1/hooks/${token}`,
76			};
77		}
78	
79		/**
80		 * Consume a webhook by its plaintext token. Marks the hook fired and
81		 * stores the payload; the caller resets the run and fires a resume pass.
82		 */
83		async consume(input: ConsumeWebhookInput): Promise<ConsumeResult> {
84			const tokenHash = createHash("sha256").update(input.token).digest("hex");
85			const hook = await this.scope().query.webhookHooks.findFirst({
86				where: eq(webhookHooks.tokenHash, tokenHash),
87			});
88			if (!hook) {
89				return { ok: false, reason: "not-found" };
90			}
91			if (hook.status !== "active") {
92				return { ok: false, reason: "already-fired" };
93			}
94			if (hook.expiresAt.getTime() < Date.now()) {
95				await this.scope()
96					.update(webhookHooks)
97					.set({ status: "expired" })
98					.where(eq(webhookHooks.id, hook.id));
99				return { ok: false, reason: "expired" };
100			}
101			await this.scope()
102				.update(webhookHooks)
103				.set({
104					status: "fired",
105					firedAt: new Date(),
106					consumePayload: {
107						instruction:
108							(hook.consumePayload as { instruction?: unknown } | null)
109								?.instruction ?? "",
110						payload: input.payload,
111					} as never,
112				})
113				.where(eq(webhookHooks.id, hook.id));
114			return {
115				ok: true,
116				hook: { ...hook, status: "fired" },
117			};
118		}
119	}
