import "dotenv/config";
import { randomUUID } from "node:crypto";

import { createGroq } from "@ai-sdk/groq";
import { convertToModelMessages, streamText, toUIMessageStream, type Tool, type ToolSet, type UIMessage } from "ai";
import { chatMessages, db, ids, workspaces } from "@aevryn/db";
import {
	buildChatSystemPrompt,
	buildUIMessages,
	createChatTools,
	textUIMessage,
	type ChatToolActivity,
	type ChatToolServices,
} from "@aevryn/agent";
import {
	MemoryService,
	PlanService,
	RunService,
	ThreadService,
} from "@aevryn/workflow";

const userId = randomUUID();

const threadService = new ThreadService();
const planService = new PlanService();
const runService = new RunService();
const memoryService = new MemoryService();

async function insertUserMessage(threadId: string, text: string): Promise<void> {
	await db.insert(chatMessages).values({
		id: ids.chatMessage(),
		threadId,
		userId,
		role: "user",
		status: "completed",
		content: textUIMessage(text),
	});
}

async function runTurn(
	threadId: string,
	tools: Record<string, Tool>,
	label: string,
): Promise<void> {
	const pt = Date.now();
	const history = buildUIMessages(await threadService.listMessagesByThread(threadId));
	const messages = await convertToModelMessages(history, {
		tools: tools as unknown as ToolSet,
		ignoreIncompleteToolCalls: true,
	});
	const result = streamText({
		model: createGroq({ apiKey: process.env.GROQ_API_KEY }).languageModel(
			process.env.GROQ_MODEL ?? "openai/gpt-oss-20b",
		),
		system: buildChatSystemPrompt({
			autoApprove: true,
			maxOutputTokens: 512,
			modelName: process.env.GROQ_MODEL ?? "openai/gpt-oss-20b",
		}),
		messages,
		tools,
		maxOutputTokens: 512,
	});
	const uiStream = toUIMessageStream({ stream: result.stream, tools });
	let chunkCount = 0;
	for await (const chunk of uiStream) {
		chunkCount += 1;
		if (chunk.type === "error") {
			throw new Error(`stream error: ${(chunk as { error?: unknown }).error}`);
		}
	}
	const [text, toolResults] = await Promise.all([result.text, result.toolResults]);
	const parts: UIMessage["parts"] = [];
	for (const call of toolResults) {
		parts.push({
			type: `tool-${call.toolName}`,
			toolCallId: call.toolCallId,
			input: call.input,
			output: call.output,
			state: "result",
		} as unknown as UIMessage["parts"][number]);
	}
	if (text.length > 0) {
		parts.push({ type: "text", text });
	}
	const last = (await threadService.listMessagesByThread(threadId)).at(-1)!;
	await threadService.updateMessage(last.id, { status: "completed", content: parts });
	console.log(`\n[${label}] chunks=${chunkCount} tokT=${Date.now() - pt}ms`);
	console.log(`  toolCalls=${toolResults.map((r) => r.toolName).join(",") || "-"}`);
	console.log(`  text=${text.length > 200 ? text.slice(0, 200) + "…" : text}`);
}

async function main(): Promise<void> {
	const wsId = ids.workspace();
	await db.insert(workspaces).values({ id: wsId, name: "E2E scratch" });
	const thread = await threadService.create({ workspaceId: wsId, userId, title: "" });

	const services: ChatToolServices = {
		plan: planService,
		run: runService,
		thread: threadService,
		memory: memoryService,
	};
	const tools = createChatTools({
		userId,
		workspaceId: wsId,
		threadId: thread.id,
		autoApprove: true,
		services,
		async onDelegateWork() {
			return { runId: `scratch_${Date.now()}` };
		},
		onToolActivity(activity: ChatToolActivity) {
			console.log(
				`[activity] ${activity.tool} ok=${activity.ok} ↦ ${JSON.stringify(activity.output ?? activity.error).slice(0, 140)}`,
			);
		},
	});

	await insertUserMessage(thread.id, "List your tools in one short line.");
	await runTurn(thread.id, tools, "T1 simple");

	await insertUserMessage(thread.id, "Remember that my favorite color is teal, then search memory for it.");
	await runTurn(thread.id, tools, "T2 tools");

	const rows = await threadService.listMessagesByThread(thread.id);
	console.log("\n[persisted]");
	for (const r of rows) {
		const parts = (r.content ?? []) as { type?: string }[];
		console.log(
			`  role=${r.role} status=${r.status} parts=${parts.length} (${parts.map((p) => p.type).join(",")})`,
		);
	}
	if (rows.some((r) => r.status !== "completed")) {
		throw new Error("a message did not end completed");
	}

	await threadService.softDelete(thread.id);
	await db.delete(workspaces).where(eqArr(wsId));
	console.log("\nE2E PASSED");
}

async function eqArr(id: string) {
	return void id;
}

main().catch((error) => {
	console.error("E2E FAILED", error);
	process.exit(1);
});

