198				detail: { sleepUntil: sleepUntil.toISOString(), reason: reason ?? null },
199			});
200			await this.setStatus(runId, "sleeping");
201		}
202	
203		/**
204		 * In-place resume: flip a sleeping/waiting/awaiting_approval run back to
205		 * `pending` and return it. The caller then fires a fresh thread/run pass
206		 * (trigger=resume). No new run row is created.
207		 */
208		async resumeTriggeredBy(runId: string): Promise<Run | undefined> {
209			const run = await this.findById(runId);
210			if (!run) {
211				return undefined;
212			}
213			if (
214				run.status === "sleeping" ||
215				run.status === "waiting" ||
216				run.status === "awaiting_approval"
217			) {
218				return (await this.setStatus(runId, "pending")) ?? run;
219			}
220			return run;
221		}
