223		/**
224		 * Runs (`status=sleeping`) whose most recent sleep activity has already
225		 * reached its wake time. Waking happens for the SAME run (trigger=resume),
226		 * mirroring webhook resume.
227		 */
228		async listSleepingDue(now: Date): Promise<Run[]> {
229			const sleeping = await this.scope().query.runs.findMany({
230				where: eq(runs.status, "sleeping"),
231				columns: { id: true },
232			});
233			const due: Run[] = [];
234			for (const run of sleeping) {
235				const [sleepActivity] = await this.scope().query.runActivities.findMany({
236					where: and(
237						eq(runActivities.runId, run.id),
238						eq(runActivities.stepLabel, "sleep"),
239					),
240					orderBy: [desc(runActivities.createdAt)],
241					limit: 1,
242				});
243				if (!sleepActivity) {
244					continue;
245				}
246				const detail = (sleepActivity.detail ?? {}) as {
247					sleepUntil?: string;
248				};
249				const until = detail.sleepUntil;
250				if (until && new Date(until).getTime() <= now.getTime()) {
251					const full = await this.findById(run.id);
252					if (full) {
253						due.push(full);
254					}
255				}
256			}
257			return due;
258		}
259	
260		/**
261		 * Replay map for a same-run bounded recovery: previously COMPLETED tool
262		 * outputs are replayed from their tool activity rows instead of
263		 * re-invoking the provider, so a write side effect can never execute twice.
264		 * Keyed by tool name (step_label); the runtime consumes each entry once.
265		 */
266		async listReplayableToolOutputs(
267			runId: string,
268		): Promise<Record<string, unknown>> {
269			const tools = await this.scope().query.runActivities.findMany({
270				where: and(
271					eq(runActivities.runId, runId),
272					eq(runActivities.type, "tool"),
273					eq(runActivities.status, "complete"),
274				),
275				orderBy: [asc(runActivities.createdAt)],
276			});
277			const replay: Record<string, unknown> = {};
278			for (const tool of tools) {
279				const name = tool.stepLabel;
280				if (!name) {
281					continue;
282				}
283				const detail = (tool.detail ?? {}) as { output?: unknown };
284				if (detail.output == null || name in replay) {
285					continue;
286				}
287				replay[name] = detail.output;
288			}
289			return replay;
290		}
291	
292		/**
293		 * Bounded recovery bookkeeping folded into run_activities: a system row
294		 * `step_label="recovery"` per attempt. Idempotent per (runId, attempt):
295		 * a concurrent failure handler cannot double-count an attempt.
296		 */
297		async recordRecoveryAttempt(runId: string, input: {
298			attempt: number;
299			failureClass: string;
300			failureCode?: string;
301			strategy: string;
302			result: "started" | "completed" | "failed";
303			detail?: Record<string, unknown>;
304		}): Promise<RunActivity | undefined> {
305			const existing = await this.scope().query.runActivities.findFirst({
306				where: and(
307					eq(runActivities.runId, runId),
308					eq(runActivities.stepLabel, "recovery"),
309					sql`${runActivities.detail}->>'attempt' = ${String(input.attempt)}`,
310				),
311			});
312			if (existing) {
313				return undefined;
314			}
315			return this.createActivity({
316				runId,
317				type: "system",
318				status: "complete",
319				stepLabel: "recovery",
320				title: `Recovery attempt ${input.attempt}`,
321				detail: {
322					attempt: input.attempt,
323					failureClass: input.failureClass,
324					failureCode: input.failureCode ?? null,
325					strategy: input.strategy,
326					result: input.result,
327					...(input.detail ?? {}),
328				},
329			});
330		}
331	
332		async countRecoveryAttempts(runId: string): Promise<number> {
333			const activities = await this.scope().query.runActivities.findMany({
334				where: and(
335					eq(runActivities.runId, runId),
336					eq(runActivities.stepLabel, "recovery"),
337				),
338				columns: { id: true },
339			});
340			return activities.length;
341		}
342	
343		async updateRecoveryResult(
344			runId: string,
345			attempt: number,
346			result: "completed" | "failed",
347			detail?: Record<string, unknown>,
348		): Promise<void> {
349			const activity = await this.scope().query.runActivities.findFirst({
350				where: and(
351					eq(runActivities.runId, runId),
352					eq(runActivities.stepLabel, "recovery"),
353					sql`${runActivities.detail}->>'attempt' = ${String(attempt)}`,
354				),
355			});
356			if (!activity) {
357				return;
358			}
359			const current = (activity.detail ?? {}) as Record<string, unknown>;
360			await this.updateActivityDetail(activity.id, {
361				...current,
362				result,
363				...detail,
364			});
365		}
366	}
