import type { UIMessage } from "ai";

export type SerializedUser = {
	id: string;
	email?: string | null;
};

export type SerializedProfile = {
	plan?: string | null;
	preferOwnKeysInShared?: boolean | null;
	onboarded: boolean;
	preAnswers?: Record<string, never> | null;
};

export type SerializedWorkspace = {
	id: string;
	name: string;
	isDefault: boolean;
	role: "owner" | "editor" | "viewer";
};

export type SerializedGroup = {
	id: string;
	name: string;
	kind: "custom" | "system";
	position: number;
	locked?: boolean | null;
	threadCount: number;
};

export type SerializedThread = {
	id: string;
	status: "active" | "queued" | "idle" | "awaiting_approval";
	boundWorkflowId: string | null;
	shareEnabled: boolean;
	lastMessageAt: string | null;
	createdAt: string;
};

export type SerializedNotification = {
	id: string;
	title: string;
	body: string | null;
	type: string;
	createdAt: string;
	readAt: string | null;
};

export type SerializedRun = {
	id: string;
	status: "pending" | "running" | "sleeping" | "waiting" | "awaiting_approval" | "completed" | "failed" | "cancelled";
	trigger: string;
	createdAt: string;
	finishedAt: string | null;
	promptSnapshot: unknown;
};

export type SerializedRunActivity = {
	id: string;
	runId: string;
	type: string;
	status: string;
	stepLabel: string | null;
	title: string | null;
	description: string | null;
	detail: unknown;
	createdAt: string;
};

export type SerializedMessage = {
	id: string;
	threadId: string;
	role: "user" | "assistant";
	status: "draft" | "queued" | "streaming" | "completed" | "failed" | "interrupted";
	content: UIMessage["parts"];
	createdAt: string;
	updatedAt: string;
};

export type SerializedApprovalRequest = {
	id: string;
	runId: string;
	threadId: string | null;
	workflowId: string | null;
	toolName: string;
	input: unknown;
	schema: unknown;
	status: "pending" | "approved" | "denied";
	autoApproved: boolean;
	createdAt: string;
};

export type SerializedWorkflow = {
	id: string;
	title: string;
	status: "active" | "paused" | "archived" | "draft";
	autoApprove: boolean;
};

export type WorkspaceHydration = {
	auth: {
		user: SerializedUser;
		profile: SerializedProfile;
		workspaces: SerializedWorkspace[];
		activeWorkspaceId: string;
	};
	workspace: {
		id: string;
		name: string;
		role: "owner" | "editor" | "viewer";
	};
	groups: Array<SerializedGroup & { threads: Array<SerializedThread & { title: string }> }>;
	notifications: SerializedNotification[];
	unreadCount: number;
	workflows: SerializedWorkflow[];
};

export type ThreadHydration = {
	thread: {
		id: string;
		title: string;
		groupId: string;
		shareEnabled: boolean;
		boundWorkflowId: string | null;
	};
	messages: SerializedMessage[];
	runs: SerializedRun[];
	activities: SerializedRunActivity[];
	pendingApprovals: SerializedApprovalRequest[];
	isMemberViewer?: boolean;
};

export type WorkspaceThread = {
	id: string;
	title: string;
	status: "active" | "queued" | "idle" | "awaiting_approval";
	boundWorkflowId: string | null;
	shareEnabled: boolean;
	lastMessageAt: string | null;
	createdAt: string;
};

import { create } from "zustand";

import type {
	SerializedProfile,
	SerializedUser,
	SerializedWorkspace,
} from "@/types/workspace";

type AuthState = {
	user: SerializedUser | null;
	profile: SerializedProfile | null;
	workspaces: SerializedWorkspace[];
	activeWorkspaceId: string | null;
	hydrate: (auth: {
		user: SerializedUser;
		profile: SerializedProfile;
		workspaces: SerializedWorkspace[];
		activeWorkspaceId: string;
	}) => void;
	setUser: (user: SerializedUser | null) => void;
	setProfile: (profile: SerializedProfile | null) => void;
	setActiveWorkspace: (workspaceId: string) => void;
	accessToken: string | null;
	setAccessToken: (token: string | null) => void;
};

export const useAuthStore = create<AuthState>((set) => ({
	user: null,
	profile: null,
	workspaces: [],
	activeWorkspaceId: null,
	accessToken: null,
	hydrate: (auth) =>
		set({
			user: auth.user,
			profile: auth.profile,
			workspaces: auth.workspaces,
			activeWorkspaceId: auth.activeWorkspaceId,
		}),
	setUser: (user) => set({ user }),
	setProfile: (profile) => set({ profile }),
	setActiveWorkspace: (activeWorkspaceId) => set({ activeWorkspaceId }),
	setAccessToken: (accessToken) => set({ accessToken }),
}));

export function isEditorOfWorkspace(
	workspaces: SerializedWorkspace[],
	workspaceId: string | null,
): boolean {
	const ws = workspaces.find((w) => w.id === workspaceId);
	return ws === undefined ? false : ws.role !== "viewer";
}

import { create } from "zustand";

import type {
	SerializedApprovalRequest,
	SerializedGroup,
	SerializedMessage,
	SerializedRun,
	SerializedRunActivity,
	SerializedThread,
	WorkspaceThread,
} from "@/types/workspace";

export type GroupNode = SerializedGroup & {
	threads: WorkspaceThread[];
};

export type MessageLike =
	| SerializedMessage
	| {
			id: string;
			role: "user" | "assistant";
			status: "streaming" | "completed";
			content: Array<{ type: "text"; text: string }>;
			createdAt: string;
	  };

type ThreadState = {
	groups: GroupNode[];
	threads: Record<string, WorkspaceThread>;
	activeThreadId: string | null;
	messagesByThread: Record<string, MessageLike[]>;
	runsByThread: Record<string, SerializedRun[]>;
	activitiesByThread: Record<string, SerializedRunActivity[]>;
	approvalsByThread: Record<string, SerializedApprovalRequest[]>;
	boundWorkflows: Record<string, string | null>;
	hydrateGroups: (groups: Array<SerializedGroup & { threads: WorkspaceThread[] }>) => void;
	hydrateThread: (threadId: string, data: {
		messages?: SerializedMessage[];
		runs?: SerializedRun[];
		activities?: SerializedRunActivity[];
		pendingApprovals?: SerializedApprovalRequest[];
	}) => void;
	setActiveThread: (threadId: string | null) => void;
	upsertMessage: (message: MessageLike) => void;
	setMessageStatus: (threadId: string, messageId: string, status: MessageLike["status"]) => void;
	appendStreamParts: (
		threadId: string,
		messageId: string,
		parts: MessageLike["content"],
	) => void;
	upsertRun: (run: SerializedRun) => void;
	upsertActivity: (activity: SerializedRunActivity) => void;
	upsertApproval: (approval: SerializedApprovalRequest) => void;
	setThreadStatus: (
		threadId: string,
		status: WorkspaceThread["status"],
	) => void;
	updateThread: (threadId: string, patch: Partial<WorkspaceThread>) => void;
	bindWorkflow: (threadId: string, workflowId: string | null) => void;
	setBoundWorkflow: (threadId: string, workflowId: string | null) => void;
	removeThread: (threadId: string) => void;
	clear: () => void;
};

function upsertIn<T extends { id: string }>(list: T[], item: T): T[] {
	const index = list.findIndex((candidate) => candidate.id === item.id);
	if (index === -1) {
		return [...list, item];
	}
	const next = [...list];
	next[index] = item;
	return next;
}

function computeThreadStatus(runs: SerializedRun[] | undefined): WorkspaceThread["status"] {
	if (!runs || runs.length === 0) {
		return "idle";
	}
	const latest = runs[0];
	if (
		latest.status === "pending" ||
		latest.status === "running" ||
		latest.status === "sleeping" ||
		latest.status === "waiting"
	) {
		return "active";
	}
	if (latest.status === "awaiting_approval") {
		return "awaiting_approval";
	}
	return "idle";
}

export const useThreadStore = create<ThreadState>((set, get) => ({
	groups: [],
	threads: {},
	activeThreadId: null,
	messagesByThread: {},
	runsByThread: {},
	activitiesByThread: {},
	approvalsByThread: {},
	boundWorkflows: {},
	hydrateGroups: (groups) => {
		const threads: Record<string, WorkspaceThread> = {};
		for (const group of groups) {
			for (const thread of group.threads) {
				threads[thread.id] = thread;
			}
		}
		set({ groups, threads });
	},
	hydrateThread: (threadId, data) => {
		set((state) => {
			const next = { ...state };
			if (data.messages) {
				next.messagesByThread = {
					...next.messagesByThread,
					[threadId]: data.messages,
				};
			}
			if (data.runs) {
				next.runsByThread = {
					...next.runsByThread,
					[threadId]: data.runs,
				};
				const status = computeThreadStatus(data.runs);
				const thread = next.threads[threadId];
				if (thread && thread.status !== status) {
					next.threads = {
						...next.threads,
						[threadId]: { ...thread, status },
					};
				}
			}
			if (data.activities) {
				next.activitiesByThread = {
					...next.activitiesByThread,
					[threadId]: data.activities,
				};
			}
			if (data.pendingApprovals) {
				next.approvalsByThread = {
					...next.approvalsByThread,
					[threadId]: data.pendingApprovals,
				};
			}
			return next;
		});
	},
	setActiveThread: (activeThreadId) => set({ activeThreadId }),
	upsertMessage: (message) =>
		set((state) => {
			const list = state.messagesByThread[message.role === "user" ? getActiveThreadId(state) : getActiveThreadId(state)] ?? [];
			const threadId = getActiveThreadId(state);
			if (!threadId) {
				return {};
			}
			const existing = state.messagesByThread[threadId] ?? [];
			return {
				messagesByThread: {
					...state.messagesByThread,
					[threadId]: upsertIn(existing, message),
				},
			};
		}),
	setMessageStatus: (threadId, messageId, status) =>
		set((state) => {
			const list = state.messagesByThread[threadId] ?? [];
			return {
				messagesByThread: {
					...state.messagesByThread,
					[threadId]: list.map((message) =>
						message.id === messageId ? { ...message, status } : message,
					),
				},
			};
		}),
	appendStreamParts: (threadId, messageId, parts) =>
		set((state) => {
			const list = state.messagesByThread[threadId] ?? [];
			return {
				messagesByThread: {
					...state.messagesByThread,
					[threadId]: list.map((message) =>
						message.id === messageId
							? { ...message, content: [...message.content, ...parts] }
							: message,
					),
				},
			};
		}),
	upsertRun: (run) => {
		const { upsertRun, setThreadStatus } = get();
		set((state) => {
			const threadId = getActiveThreadId(state);
			if (!threadId) {
				return {};
			}
			const list = state.runsByThread[threadId] ?? [];
