import type { UIMessage } from "ai";
import { create } from "zustand";

import type {
	SerializedApprovalRequest,
	SerializedGroup,
	SerializedMessage,
	SerializedRun,
	SerializedRunActivity,
	WorkspaceThread,
} from "@/types/workspace";

export type GroupNode = SerializedGroup & {
	threads: WorkspaceThread[];
};

export type StreamMessage = {
	id: string;
	role: "user" | "assistant";
	status: "draft" | "streaming" | "completed" | "failed";
	content: UIMessage["parts"];
	createdAt: string;
};

export type StoredMessage = SerializedMessage | StreamMessage;

type ThreadState = {
	groups: GroupNode[];
	threads: Record<string, WorkspaceThread>;
	activeThreadId: string | null;
	messagesByThread: Record<string, StoredMessage[]>;
	runsByThread: Record<string, SerializedRun[]>;
	activitiesByThread: Record<string, SerializedRunActivity[]>;
	approvalsByThread: Record<string, SerializedApprovalRequest[]>;
	hydrateGroups: (
		groups: Array<SerializedGroup & { threads: WorkspaceThread[] }>,
	) => void;
	hydrateThread: (
		threadId: string,
		data: {
			messages?: SerializedMessage[];
			runs?: SerializedRun[];
			activities?: SerializedRunActivity[];
			pendingApprovals?: SerializedApprovalRequest[];
		},
	) => void;
	setActiveThread: (threadId: string | null) => void;
	upsertMessage: (message: StoredMessage, threadId?: string) => void;
	appendMessageContent: (
		threadId: string,
		messageId: string,
		parts: UIMessage["parts"],
	) => void;
	setMessages: (threadId: string, messages: StoredMessage[]) => void;
	upsertRun: (threadId: string, run: SerializedRun) => void;
	setRuns: (threadId: string, runs: SerializedRun[]) => void;
	upsertActivity: (threadId: string, activity: SerializedRunActivity) => void;
	upsertApproval: (threadId: string, approval: SerializedApprovalRequest) => void;
	updateApprovalStatus: (
		threadId: string,
		approvalId: string,
		status: "approved" | "denied",
		autoApproved?: boolean,
		resolvedAt?: string,
	) => void;
	setThreadStatus: (threadId: string, status: WorkspaceThread["status"]) => void;
	updateThread: (threadId: string, patch: Partial<WorkspaceThread>) => void;
	removeThread: (threadId: string) => void;
	clear: () => void;
};

function upsertById<T extends { id: string }>(list: T[], item: T): T[] {
	const index = list.findIndex((candidate) => candidate.id === item.id);
	if (index === -1) {
		return [item, ...list];
	}
	const next = [...list];
	next[index] = item;
	return next;
}

function statusFromRuns(runs: SerializedRun[]): WorkspaceThread["status"] {
	if (runs.length === 0) {
		return "idle";
	}
	const latest = runs[0];
	switch (latest.status) {
		case "pending":
		case "running":
		case "sleeping":
		case "waiting":
			return "active";
		case "awaiting_approval":
			return "awaiting_approval";
		default:
			return "idle";
	}
}

function withNewThreadStatus(
	state: ThreadState,
	threadId: string,
): Partial<ThreadState> | null {
	const thread = state.threads[threadId];
	const runStatus = statusFromRuns(state.runsByThread[threadId] ?? []);
	if (!thread || thread.status === runStatus) {
		return null;
	}
	return {
		threads: { ...state.threads, [threadId]: { ...thread, status: runStatus } },
	};
}

export const useThreadStore = create<ThreadState>((set, get) => ({
	groups: [],
	threads: {},
	activeThreadId: null,
	messagesByThread: {},
	runsByThread: {},
	activitiesByThread: {},
	approvalsByThread: {},
	hydrateGroups: (groups) => {
		const threads: Record<string, WorkspaceThread> = {};
		for (const group of groups) {
			for (const thread of group.threads) {
				threads[thread.id] = thread;
			}
		}
		set({ groups, threads });
	},
	hydrateThread: (threadId, data) =>
		set((state) => {
			const next: Partial<ThreadState> = {};
			if (data.messages) {
				next.messagesByThread = {
					...state.messagesByThread,
					[threadId]: data.messages,
				};
			}
			if (data.runs) {
				const runs = [...data.runs].sort((a, b) =>
					b.createdAt.localeCompare(a.createdAt),
				);
				next.runsByThread = {
					...state.runsByThread,
					[threadId]: runs,
				};
				const statusPatch = withNewThreadStatus(
					{ ...state, runsByThread: { ...state.runsByThread, [threadId]: runs } },
					threadId,
				);
				if (statusPatch) {
					Object.assign(next, statusPatch);
				}
			}
			if (data.activities) {
				next.activitiesByThread = {
					...state.activitiesByThread,
					[threadId]: data.activities,
				};
			}
			if (data.pendingApprovals) {
				next.approvalsByThread = {
					...state.approvalsByThread,
					[threadId]: data.pendingApprovals,
				};
			}
			return next;
		}),
	setActiveThread: (activeThreadId) => set({ activeThreadId }),
	upsertMessage: (message, threadId) =>
		set((state) => {
			const target = threadId ?? get().activeThreadId;
			if (!target) {
				return {};
			}
			const list = state.messagesByThread[target] ?? [];
			return {
				messagesByThread: {
					...state.messagesByThread,
					[target]: upsertById(list, message),
				},
			};
		}),
	appendMessageContent: (threadId, messageId, parts) =>
		set((state) => {
			const list = state.messagesByThread[threadId] ?? [];
			return {
				messagesByThread: {
					...state.messagesByThread,
					[threadId]: list.map((message) =>
						message.id === messageId
							? { ...message, content: [...message.content, ...parts] }
							: message,
					),
				},
			};
		}),
	setMessages: (threadId, messages) =>
		set((state) => ({
			messagesByThread: {
				...state.messagesByThread,
				[threadId]: messages,
			},
		})),
	upsertRun: (threadId, run) =>
		set((state) => {
			const list = state.runsByThread[threadId] ?? [];
			const runs = [...upsertById(list, run)].sort((a, b) =>
				b.createdAt.localeCompare(a.createdAt),
			);
			const next: Partial<ThreadState> = {
				runsByThread: { ...state.runsByThread, [threadId]: runs },
			};
			const statusPatch = withNewThreadStatus(
				{ ...state, runsByThread: { ...state.runsByThread, [threadId]: runs } },
				threadId,
			);
			if (statusPatch) {
				Object.assign(next, statusPatch);
			}
			return next;
		}),
	setRuns: (threadId, runs) =>
		set((state) => {
			const sorted = [...runs].sort((a, b) =>
				b.createdAt.localeCompare(a.createdAt),
			);
			const next: Partial<ThreadState> = {
				runsByThread: { ...state.runsByThread, [threadId]: sorted },
			};
			const statusPatch = withNewThreadStatus(
				{ ...state, runsByThread: { ...state.runsByThread, [threadId]: sorted } },
				threadId,
			);
			if (statusPatch) {
				Object.assign(next, statusPatch);
			}
			return next;
		}),
	upsertActivity: (threadId, activity) =>
		set((state) => {
			const list = state.activitiesByThread[threadId] ?? [];
			return {
				activitiesByThread: {
					...state.activitiesByThread,
					[threadId]: upsertById(list, activity),
				},
			};
		}),
	upsertApproval: (threadId, approval) =>
		set((state) => {
			const list = state.approvalsByThread[threadId] ?? [];
			return {
				approvalsByThread: {
					...state.approvalsByThread,
					[threadId]: upsertById(list, approval),
				},
			};
		}),
	updateApprovalStatus: (threadId, approvalId, status, autoApproved = false) =>
		set((state) => {
			const list = state.approvalsByThread[threadId] ?? [];
			return {
				approvalsByThread: {
					...state.approvalsByThread,
					[threadId]: list.map((approval) =>
						approval.id === approvalId
							? {
									...approval,
									status,
									autoApproved,
									resolvedAt:
										approval.resolvedAt ??
										new Date().toISOString(),
								}
							: approval,
					),
				},
			};
		}),
	setThreadStatus: (threadId, status) =>
		set((state) => {
			if (!state.threads[threadId]) {
				return {};
			}
			return {
				threads: {
					...state.threads,
					[threadId]: { ...state.threads[threadId], status },
				},
			};
		}),
	updateThread: (threadId, patch) =>
		set((state) => {
			if (!state.threads[threadId]) {
				return {};
			}
			return {
				threads: {
					...state.threads,
					[threadId]: { ...state.threads[threadId], ...patch },
				},
			};
		}),
	removeThread: (threadId) =>
		set((state) => {
			const threads = { ...state.threads };
			delete threads[threadId];
			const messagesByThread = { ...state.messagesByThread };
			delete messagesByThread[threadId];
			const runsByThread = { ...state.runsByThread };
			delete runsByThread[threadId];
			const activitiesByThread = { ...state.activitiesByThread };
			delete activitiesByThread[threadId];
			const approvalsByThread = { ...state.approvalsByThread };
			delete approvalsByThread[threadId];
			const groups = state.groups.map((group) => ({
				...group,
				threads: group.threads.filter((thread) => thread.id !== threadId),
			}));
			const active = state.activeThreadId === threadId ? null : state.activeThreadId;
			return {
				groups,
				threads,
				messagesByThread,
				runsByThread,
				activitiesByThread,
				approvalsByThread,
				activeThreadId: active,
			};
		}),
	clear: () =>
		set({
			groups: [],
			threads: {},
			activeThreadId: null,
			messagesByThread: {},
			runsByThread: {},
			activitiesByThread: {},
			approvalsByThread: {},
		}),
}));

export function selectThreadsByGroup(groups: GroupNode[], groupId: string) {
	const group = groups.find((candidate) => candidate.id === groupId);
	return group ? group.threads : [];
}

