import { create } from "zustand";

export type ComposerFile = {
	id: string;
	name: string;
	size: number;
	type: string;
	url: string;
	uploading: boolean;
	error?: string | null;
};

export type ComposerQueueItem = {
	id: string;
	text: string;
	files: ComposerFile[];
	status: "queued" | "running" | "error";
};

type ComposerState = {
	value: string;
	files: ComposerFile[];
	queue: ComposerQueueItem[];
	isActive: boolean;
	error: string | null;
	setValue: (value: string) => void;
	setFiles: (files: ComposerFile[]) => void;
	setQueue: (queue: ComposerQueueItem[]) => void;
	enqueue: (item: ComposerQueueItem) => void;
	removeQueued: (id: string) => void;
	editQueued: (id: string, text: string) => void;
	setIsActive: (active: boolean) => void;
	setError: (error: string | null) => void;
	reset: () => void;
};

export const useComposerStore = create<ComposerState>((set) => ({
	value: "",
	files: [],
	queue: [],
	isActive: false,
	error: null,
	setValue: (value) => set({ value }),
	setFiles: (files) => set({ files }),
	setQueue: (queue) => set({ queue }),
	enqueue: (item) => set((state) => ({ queue: [...state.queue, item] })),
	removeQueued: (id) =>
		set((state) => ({ queue: state.queue.filter((item) => item.id !== id) })),
	editQueued: (id, text) =>
		set((state) => ({
			queue: state.queue.map((item) =>
				item.id === id ? { ...item, text } : item,
			),
		})),
	setIsActive: (isActive) => set({ isActive, error: null }),
	setError: (error) => set({ error }),
	reset: () =>
		set({ value: "", files: [], queue: [], isActive: false, error: null }),
}));

import { create } from "zustand";

import type { SerializedNotification } from "@/types/workspace";

type SidebarState = {
	collapsed: Record<string, boolean>;
	search: string;
	notifications: SerializedNotification[];
	unreadCount: number;
	toggleCollapsed: (key: string) => void;
	setCollapsed: (key: string, collapsed: boolean) => void;
	setSearch: (search: string) => void;
	hydrateNotifications: (notifications: SerializedNotification[]) => void;
	setUnreadCount: (count: number) => void;
	markRead: (id: string) => void;
	markAllRead: () => void;
	pushNotification: (notification: SerializedNotification) => void;
};

export const useSidebarStore = create<SidebarState>((set, get) => ({
	collapsed: {},
	search: "",
	notifications: [],
	unreadCount: 0,
	toggleCollapsed: (key) =>
		set((state) => ({ collapsed: { ...state.collapsed, [key]: !state.collapsed[key] } })),
	setCollapsed: (key, collapsed) =>
		set((state) => ({ collapsed: { ...state.collapsed, [key]: collapsed } })),
	setSearch: (search) => set({ search }),
	hydrateNotifications: (notifications) =>
		set({
			notifications,
			unreadCount: notifications.filter((n) => n.readAt === null).length,
		}),
	setUnreadCount: (count) => set({ unreadCount: count }),
	markRead: (id) =>
		set((state) => {
			const notifications = state.notifications.map((notification) =>
				notification.id === id && notification.readAt === null
					? { ...notification, readAt: new Date().toISOString() }
					: notification,
			);
			return {
				notifications,
				unreadCount: notifications.filter((n) => n.readAt === null).length,
			};
		}),
	markAllRead: () =>
		set((state) => ({
			notifications: state.notifications.map((notification) =>
				notification.readAt === null
					? { ...notification, readAt: new Date().toISOString() }
					: notification,
			),
			unreadCount: 0,
		})),
	pushNotification: (notification) =>
		set((state) => {
			const exists = state.notifications.some((n) => n.id === notification.id);
			if (exists) {
				return {};
			}
			return {
				notifications: [notification, ...state.notifications],
				unreadCount: state.unreadCount + (notification.readAt === null ? 1 : 0),
			};
		}),
}));

export function selectUnreadCount(state: SidebarState): number {
	return state.unreadCount;
}

export function selectNotifications(state: SidebarState): SerializedNotification[] {
	return state.notifications;
}

import { create } from "zustand";

type UiState = {
	notificationsOpen: boolean;
	settingsOpen: boolean;
	settingsSection: string;
	renameOpen: boolean;
	renameThreadId: string | null;
	shareOpen: boolean;
	shareThreadId: string | null;
