	closeRename: () => void;
	openShare: (threadId: string) => void;
	closeShare: () => void;
	setWorkflowDialogOpen: (open: boolean) => void;
};

export const useUiStore = create<UiState>((set) => ({
	notificationsOpen: false,
	settingsOpen: false,
	settingsSection: "general",
	renameOpen: false,
	renameThreadId: null,
	shareOpen: false,
	shareThreadId: null,
	workflowDialogOpen: false,
	setNotificationsOpen: (notificationsOpen) => set({ notificationsOpen }),
	setSettingsOpen: (settingsOpen, section) =>
		set({
			settingsOpen,
			settingsSection: section ?? "general",
		}),
	setSettingsSection: (settingsSection) => set({ settingsSection }),
	openRename: (renameThreadId) => set({ renameOpen: true, renameThreadId }),
	closeRename: () => set({ renameOpen: false, renameThreadId: null }),
	openShare: (shareThreadId) => set({ shareOpen: true, shareThreadId }),
	closeShare: () => set({ shareOpen: false, shareThreadId: null }),
	setWorkflowDialogOpen: (workflowDialogOpen) => set({ workflowDialogOpen }),
}));

