import { useCallback, useRef, useState } from "react";

import { getBrowserSupabase } from "@aevryn/auth/client";

import { useAuthStore } from "@/stores/auth-store";
import { useComposerStore } from "@/stores/composer-store";
import {
	useThreadStore,
	type StoredMessage,
} from "@/stores/thread-store";

const tempId = (role: "user" | "assistant") =>
	`temp-${role}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

type StreamPart =
	| { type: "text-start"; id: string }
	| { type: "text-delta"; id: string; delta: string }
	| { type: "text-end"; id: string }
	| { type: "start"; messageId?: string }
	| { type: "finish"; finishReason?: string }
	| { type: "error"; error?: unknown }
	| {
			type:
				| "reasoning-start"
				| "reasoning-delta"
				| "reasoning-end"
				| "file-start"
				| "file-end"
				| "file-delta"
				| "tool-call"
				| "tool-input-delta";
			id?: string;
	  };

export type ThreadChatState = "idle" | "streaming";

export function useThreadChat(threadId: string) {
	const [status, setStatus] = useState<ThreadChatState>("idle");
	const [runId, setRunId] = useState<string | null>(null);
	const [error, setError] = useState<string | null>(null);
	const abortRef = useRef<AbortController | null>(null);
	const textBufferRef = useRef<string>("");
	const assistantIdRef = useRef<string | null>(null);

	const { accessToken } = useAuthStore((state) => ({
		accessToken: state.accessToken,
	}));

	const send = useCallback(
		async (text: string) => {
			if (status === "streaming") {
				return;
			}
			const trimmed = text.trim();
			if (!trimmed) {
				return;
			}
			const store = useThreadStore.getState();
			const composer = useComposerStore.getState();
			const activeThreadId = store.activeThreadId;
			if (!activeThreadId) {
				return;
			}

			const userMessage: StoredMessage = {
				id: tempId("user"),
				role: "user",
				status: "completed",
				content: [{ type: "text", text: trimmed }],
				createdAt: new Date().toISOString(),
			};
			const assistantId = tempId("assistant");
			const assistantMessage: StoredMessage = {
				id: assistantId,
				role: "assistant",
				status: "streaming",
				content: [],
				createdAt: new Date().toISOString(),
			};
			assistantIdRef.current = assistantId;
			textBufferRef.current = "";
			store.upsertMessage(userMessage, activeThreadId);
			store.upsertMessage(assistantMessage, activeThreadId);
			setStatus("streaming");
			setError(null);
			store.setThreadStatus(activeThreadId, "active");

			const controller = new AbortController();
			abortRef.current = controller;

			try {
				const response = await fetch("/api/chat", {
					method: "POST",
					headers: {
						"content-type": "application/json",
						...(accessToken ? { authorization: `Bearer ${accessToken}` } : {}),
					},
					body: JSON.stringify({
						threadId: activeThreadId,
						message: trimmed,
						maxOutputTokens: composerQuality(activeThreadId),
					}),
					signal: controller.signal,
				});

				const contentType = response.headers.get("content-type") ?? "";

				if (contentType.includes("text/event-stream")) {
					if (!response.body) {
						throw new Error("No response body.");
					}
					const reader = response.body.getReader();
					const decoder = new TextDecoder();
					let buffer = "";
					let finished = false;
					while (true) {
						const { done, value } = await reader.read();
						if (done) {
							break;
						}
						buffer += decoder.decode(value, { stream: true });
						const lines = buffer.split("\n");
						buffer = lines.pop() ?? "";
						for (const line of lines) {
							const event = parseSseLine(line);
							if (event === null) {
								continue;
							}
							if (event.type === "text-delta") {
								textBufferRef.current += event.delta;
								useThreadStore.getState().appendMessageContent(
									activeThreadId,
									assistantId,
									[{ type: "text", text: event.delta }],
								);
							} else if (event.type === "finish") {
								finished = true;
							} else if (event.type === "error") {
								finished = true;
								setError("The assistant encountered an error mid-stream.");
							}
						}
						if (finished) {
							break;
						}
					}
					finishAssistant(activeThreadId, assistantId);
					return;
				}

				const json = await response.json().catch(() => null);
				if (!response.ok) {
					const message =
						(typeof json?.error?.message === "string"
							? json.error.message
							: "Chat request failed.") ?? "";
					throw new Error(message);
				}
				if (json?.data?.queued === true) {
					store.setMessageStatus(
						activeThreadId,
						assistantId,
						"completed",
					);
					const queued: StoredMessage = {
						id: tempId("user"),
						role: "user",
						status: "draft",
						content: [{ type: "text", text: trimmed }],
						createdAt: new Date().toISOString(),
					};
					store.upsertMessage(queued, activeThreadId);
					return;
				}
				finishAssistant(activeThreadId, assistantId);
			} catch (caught) {
				if (controller.signal.aborted) {
					finishAssistant(activeThreadId, assistantId, "interrupted");
					return;
				}
				const message =
					caught instanceof Error ? caught.message : "Chat failed.";
				store.setMessageStatus(activeThreadId, assistantId, "failed");
				store.appendMessageContent(activeThreadId, assistantId, [
					{ type: "text", text: `Error: ${message}` },
				]);
				setError(message);
			} finally {
				abortRef.current = null;
				setStatus("idle");
				refreshThreadStatus(activeThreadId);
			}
		},
		[status, accessToken],
	);

	const stop = useCallback(() => {
		abortRef.current?.abort();
	}, []);

	return {
		status,
		runId,
		error,
		send,
		stop,
		dismissError: () => setError(null),
	};

	function finishAssistant(
		thread: string,
		assistant: string,
		nextStatus: "completed" | "interrupted" = "completed",
	) {
		const store = useThreadStore.getState();
		if (nextStatus === "interrupted") {
			store.setMessageStatus(thread, assistant, "completed");
			store.appendMessageContent(thread, assistant, [
				{ type: "text", text: textBufferRef.current },
			]);
			return;
		}
		const current = store.messagesByThread[thread]?.find(
			(m) => m.id === assistant,
		);
		if (current && current.content.length === 0) {
			store.appendMessageContent(thread, assistant, [
				{ type: "text", text: textBufferRef.current },
			]);
		}
		store.setMessageStatus(thread, assistant, "completed");
	}

	function composerQuality(thread: string): number | undefined {
		const composer = useComposerStore.getState();
		return composerQualityFor(thread);
	}

	function composerQualityFor(_thread: string): number | undefined {
		return useComposerStore.getState().quality ?? undefined;
	}

	function refreshThreadStatus(thread: string) {
		useThreadStore.getState().setThreadStatus(thread, "idle");
	}

	function parseSseLine(line: string): StreamPart | null {
		const trimmed = line.trim();
		if (!trimmed.startsWith("data:")) {
			return null;
		}
		const raw = trimmed.slice(5).trim();
		if (raw === "[DONE]") {
			return null;
		}
		try {
			return JSON.parse(raw) as StreamPart;
		} catch {
			return null;
		}
	}
}

export async function fetchPendingApprovals() {
	const { activeWorkspaceId } = useAuthStore.getState();
	if (!activeWorkspaceId) {
		return [];
	}
	const supabase = getBrowserSupabase();
	const { data, error } = await supabase
		.from("approval_requests")
		.select("id,run_id,thread_id,workflow_id,tool_name,input,schema,status,auto_approved,created_at")
		.eq("status", "pending")
		.is("thread_id", null)
		.lt("created_at", new Date().toISOString());
	if (error) {
		return [];
	}
	return data ?? [];
}

