import { useCallback, useRef, useState } from "react";

import { useComposerStore } from "@/stores/composer-store";
import { useThreadStore, type StoredMessage } from "@/stores/thread-store";

const tempId = (role: "user" | "assistant") =>
	`temp-${role}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

type StreamPart =
	| { type: "start"; messageId?: string }
	| { type: "text-start"; id: string }
	| { type: "text-delta"; id: string; delta: string }
	| { type: "text-end"; id: string }
	| { type: "reasoning-start" | "reasoning-end"; id: string }
	| { type: "reasoning-delta"; id: string; delta: string }
	| { type: "tool-call" | "tool-input-delta"; toolCallId?: string }
	| { type: "finish"; finishReason?: string }
	| { type: "error"; error?: unknown };

export type ThreadChatState = "idle" | "streaming";

export interface UseThreadChat {
	status: ThreadChatState;
	error: string | null;
	send: (text: string) => Promise<void>;
	stop: () => void;
	dismissError: () => void;
}

export function useThreadChat(threadId: string): UseThreadChat {
	const [status, setStatus] = useState<ThreadChatState>("idle");
	const [error, setError] = useState<string | null>(null);
	const abortRef = useRef<AbortController | null>(null);
	const textBufferRef = useRef<string>("");

	const send = useCallback(
		async (text: string) => {
			const trimmed = text.trim();
			if (!trimmed) {
				return;
			}
			const store = useThreadStore.getState();
			const composer = useComposerStore.getState();
			const assistantId = tempId("assistant");
			const userId = tempId("user");
			textBufferRef.current = "";

			store.upsertMessage(
				{
					id: userId,
					role: "user",
					status: "completed",
					content: [{ type: "text", text: trimmed }],
					createdAt: new Date().toISOString(),
				},
				threadId,
			);
			store.upsertMessage(
				{
					id: assistantId,
					role: "assistant",
					status: "streaming",
					content: [],
					createdAt: new Date().toISOString(),
				},
				threadId,
			);
			store.setThreadStatus(threadId, "active");
			setStatus("streaming");
			setError(null);

			const controller = new AbortController();
			abortRef.current = controller;

			const finalize = (nextStatus: StoredMessage["status"]) => {
				const current = useThreadStore
					.getState()
					.messagesByThread[threadId]?.find((m) => m.id === assistantId);
				if (current && current.content.length === 0 && textBufferRef.current) {
					useThreadStore.getState().appendMessageContent(threadId, assistantId, [
						{ type: "text", text: textBufferRef.current },
					]);
				}
				useThreadStore.getState().setMessageStatus(threadId, assistantId, nextStatus);
			};

			try {
				const response = await fetch("/api/chat", {
					method: "POST",
					headers: { "content-type": "application/json" },
					body: JSON.stringify({
						threadId,
						message: trimmed,
						maxOutputTokens: composer.quality,
					}),
					signal: controller.signal,
				});

				const contentType = response.headers.get("content-type") ?? "";

				if (contentType.includes("text/event-stream")) {
					if (!response.body) {
						throw new Error("No response body.");
					}
					const reader = response.body.getReader();
					const decoder = new TextDecoder();
					let buffer = "";
					let done = false;
					while (!done) {
						const chunk = await reader.read();
						if (chunk.done) {
							break;
						}
						buffer += decoder.decode(chunk.value, { stream: true });
						const lines = buffer.split("\n");
						buffer = lines.pop() ?? "";
						for (const line of lines) {
							const part = parseSseLine(line);
							if (!part) {
								continue;
							}
							if (part.type === "text-delta") {
								textBufferRef.current += part.delta;
								useThreadStore.getState().appendMessageContent(
									threadId,
									assistantId,
									[{ type: "text", text: part.delta }],
								);
							} else if (part.type === "finish") {
								done = true;
							} else if (part.type === "error") {
								done = true;
								setError("The assistant encountered an error mid-stream.");
								finalize("failed");
							}
						}
					}
					if (!useThreadStore.getState().messagesByThread[threadId]) {
						return;
					}
					finalize("completed");
					return;
				}

				const json = (await response.json().catch(() => null)) as {
					data?: { queued?: boolean; messageId?: string };
					error?: { message?: string } | null;
				} | null;

				if (!response.ok) {
					throw new Error(
						json?.error?.message ?? "Chat request failed.",
					);
				}
				if (json?.data?.queued) {
					useThreadStore.getState().setMessageStatus(threadId, assistantId, "completed");
					useThreadStore
						.getState()
						.setThreadStatus(threadId, "active");
					await refreshQueue(threadId);
					return;
				}
				finalize("completed");
			} catch (caught) {
				if (controller.signal.aborted) {
					finalize("completed");
					return;
				}
				const message =
					caught instanceof Error ? caught.message : "Chat failed.";
				useThreadStore.getState().setMessageStatus(threadId, assistantId, "failed");
				setError(message);
			} finally {
				abortRef.current = null;
				setStatus("idle");
				await refreshQueue(threadId);
			}
		},
		[threadId],
	);

	const stop = useCallback(() => {
		abortRef.current?.abort();
	}, []);

	return {
		status,
		error,
		send,
		stop,
		dismissError: () => setError(null),
	};
}

export async function refreshQueue(threadId: string): Promise<void> {
	try {
		const response = await fetch(`/api/queue?threadId=${encodeURIComponent(threadId)}`, {
			headers: { "cache-control": "no-store" },
		});
		if (!response.ok) {
			return;
		}
		const json = (await response.json()) as {
			data?: Array<{ id: string; content: unknown }>;
		};
		const items = (json.data ?? []).map((row) => ({
			id: row.id,
			text: extractText(row.content),
			files: [],
			status: "queued" as const,
		}));
		useComposerStore.getState().setQueue(items);
	} catch {
		// Queue refresh is best-effort; realtime keeps it eventually consistent.
	}
}

function extractText(content: unknown): string {
	if (!Array.isArray(content)) {
		return "";
	}
	return content
		.filter(
			(part): part is { type: "text"; text: string } =>
				typeof part === "object" &&
				part !== null &&
				(part as { type?: string }).type === "text" &&
				typeof (part as { text?: unknown }).text === "string",
		)
		.map((part) => part.text)
		.join("");
}

