import { useEffect } from "react";

import { getBrowserSupabase } from "@aevryn/auth/client";
import type { RealtimePostgresChangesPayload } from "@supabase/supabase-js";

import { refreshQueue } from "@/hooks/use-thread-chat";
import { useSidebarStore } from "@/stores/sidebar-store";
import { useThreadStore } from "@/stores/thread-store";
import type {
	SerializedApprovalRequest,
	SerializedMessage,
	SerializedNotification,
	SerializedRun,
	SerializedRunActivity,
} from "@/types/workspace";

type Row = Record<string, unknown>;

const str = (value: unknown, fallback = ""): string =>
	typeof value === "string" ? value : fallback;
const nullableStr = (value: unknown): string | null =>
	typeof value === "string" ? value : null;

function mapMessage(row: Row): SerializedMessage {
	return {
		id: str(row.id),
		threadId: str(row.thread_id),
		role: row.role === "assistant" ? "assistant" : "user",
		status: (row.status as SerializedMessage["status"]) ?? "completed",
		content: (row.content as SerializedMessage["content"]) ?? [],
		createdAt: str(row.created_at, new Date().toISOString()),
		updatedAt: str(row.updated_at, new Date().toISOString()),
	};
}

function mapRun(row: Row): SerializedRun {
	return {
		id: str(row.id),
		status: (row.status as SerializedRun["status"]) ?? "pending",
		trigger: str(row.trigger),
		createdAt: str(row.created_at, new Date().toISOString()),
		finishedAt: nullableStr(row.finished_at),
		promptSnapshot: row.prompt_snapshot ?? null,
	};
}

function mapActivity(row: Row): SerializedRunActivity {
	return {
		id: str(row.id),
		runId: str(row.run_id),
		type: str(row.type),
		status: str(row.status),
		stepLabel: nullableStr(row.step_label),
		title: nullableStr(row.title),
		description: nullableStr(row.description),
		detail: row.detail ?? null,
		createdAt: str(row.created_at, new Date().toISOString()),
	};
}

function mapApproval(row: Row): SerializedApprovalRequest {
	return {
		id: str(row.id),
		runId: str(row.run_id),
		threadId: nullableStr(row.thread_id),
		workflowId: nullableStr(row.workflow_id),
		toolName: str(row.tool_name),
		input: row.input ?? null,
		schema: row.schema ?? null,
		status: (row.status as SerializedApprovalRequest["status"]) ?? "pending",
		autoApproved: row.auto_approved === true,
		createdAt: str(row.created_at, new Date().toISOString()),
	};
}

function mapNotification(row: Row): SerializedNotification {
	return {
		id: str(row.id),
		title: str(row.title),
		body: nullableStr(row.body),
		type: str(row.type),
		createdAt: str(row.created_at, new Date().toISOString()),
		readAt: nullableStr(row.read_at),
	};
}

function handleMessageRow(payload: RealtimePostgresChangesPayload<Row>): void {
	const row =
		payload.eventType === "DELETE"
			? (payload.old as Row)
			: (payload.new as Row);
	if (payload.eventType === "DELETE") {
		return;
	}
	const message = mapMessage(row);
	if (message.status === "queued") {
		void refreshQueue(message.threadId);
		return;
	}
	const store = useThreadStore.getState();
	// Reconcile the optimistic user message against the persisted row.
	if (message.role === "user") {
		const list = store.messagesByThread[message.threadId] ?? [];
		const firstText = message.content.find(
			(part) => part.type === "text",
		);
		const text =
			firstText && "text" in firstText ? firstText.text : "";
		const next = list.filter(
			(candidate) =>
				!(
					candidate.id.startsWith("temp-user-") &&
					candidate.content.some(
						(part) => part.type === "text" && part.text === text,
					)
				),
		);
		store.setMessages(message.threadId, next);
	}
	store.upsertMessage(message, message.threadId);
}

export function useRealtimeThread(threadId: string | null): void {
	useEffect(() => {
		if (!threadId) {
			return;
		}
		const supabase = getBrowserSupabase();
		const store = useThreadStore.getState();

		const channel = supabase
			.channel(`thread:${threadId}`)
			.on(
				"postgres_changes",
				{
					event: "*",
					schema: "public",
					table: "chat_messages",
					filter: `thread_id=eq.${threadId}`,
				},
				(payload) => handleMessageRow(payload as RealtimePostgresChangesPayload<Row>),
			)
			.on(
				"postgres_changes",
				{
					event: "*",
					schema: "public",
					table: "runs",
					filter: `thread_id=eq.${threadId}`,
				},
				(payload) => {
					if (payload.eventType === "DELETE") {
						return;
					}
					store.upsertRun(threadId, mapRun(payload.new as Row));
				},
			)
			.on(
				"postgres_changes",
				{ event: "*", schema: "public", table: "run_activities" },
				(payload) => {
					if (payload.eventType === "DELETE") {
						return;
					}
					const activity = mapActivity(payload.new as Row);
					const runs = useThreadStore.getState().runsByThread[threadId] ?? [];
					if (runs.some((run) => run.id === activity.runId)) {
						useThreadStore.getState().upsertActivity(threadId, activity);
					}
				},
			)
			.on(
				"postgres_changes",
				{
					event: "*",
					schema: "public",
					table: "approval_requests",
					filter: `thread_id=eq.${threadId}`,
				},
				(payload) => {
					if (payload.eventType === "DELETE") {
						return;
					}
					useThreadStore
						.getState()
						.upsertApproval(threadId, mapApproval(payload.new as Row));
				},
			)
			.subscribe();

		return () => {
			void supabase.removeChannel(channel);
		};
	}, [threadId]);
}

export function useRealtimeNotifications(userId: string | null): void {
	useEffect(() => {
		if (!userId) {
			return;
		}
		const supabase = getBrowserSupabase();
		const channel = supabase
			.channel(`notifications:${userId}`)
			.on(
				"postgres_changes",
				{
					event: "INSERT",
					schema: "public",
					table: "notifications",
					filter: `user_id=eq.${userId}`,
				},
				(payload) => {
					useSidebarStore
						.getState()
						.pushNotification(mapNotification(payload.new as Row));
				},
			)
			.subscribe();

		return () => {
			void supabase.removeChannel(channel);
		};
	}, [userId]);
}

