import { z } from "zod";

import { requireUser } from "@aevryn/auth";
import { inngest, threadRunEvent } from "@aevryn/inngest";
import { MemberService, RunService, ThreadService } from "@aevryn/workflow";

import { createServerSupabaseForNext } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const threadService = new ThreadService();
const memberService = new MemberService();
const runService = new RunService();

function jsonError(status: number, code: string, message: string): Response {
	return Response.json(
		{ data: null, error: { code, message, details: null }, meta: {} },
		{ status, headers: { "cache-control": "no-store" } },
	);
}

function jsonOk(data: unknown): Response {
	return Response.json(
		{ data, error: null, meta: {} },
		{ headers: { "cache-control": "no-store" } },
	);
}

const runSchema = z.object({
	prompt: z.string().min(1).max(20_000).optional(),
	modelContextCapChars: z.number().int().positive().max(2_000_000).optional(),
});

export async function POST(
	request: Request,
	ctx: { params: Promise<{ id: string }> },
): Promise<Response> {
	const supabase = await createServerSupabaseForNext();
	let user: { id: string };
	try {
		user = await requireUser(supabase);
	} catch {
		return jsonError(401, "UNAUTHENTICATED", "Sign in first.");
	}
	const { id } = await ctx.params;

	let body: unknown;
	try {
		body = await request.json();
	} catch {
		body = null;
	}
	const parsed = runSchema.safeParse(body);
	if (!parsed.success) {
		return jsonError(400, "INVALID_PAYLOAD", "Invalid run payload.");
	}

	const thread = await threadService.findById(id);
	if (!thread || thread.deletedAt) {
		return jsonError(404, "THREAD_NOT_FOUND", "Thread does not exist.");
	}
	const members = await memberService.listByUser(user.id);
	const canAccess =
		thread.userId === user.id ||
		members.some((m) => m.workspaceId === thread.workspaceId);
	if (!canAccess) {
		return jsonError(403, "FORBIDDEN", "You do not have access to this thread.");
	}

	let prompt = parsed.data.prompt;
	if (!prompt) {
		const messages = await threadService.listMessagesByThread(id);
		const lastUser = [...messages].reverse().find((m) => m.role === "user");
		prompt = extractText(lastUser?.content);
	}
	if (!prompt) {
		return jsonError(400, "NO_PROMPT", "A prompt is required to start a run.");
	}

	const run = await runService.create({
		threadId: id,
		userId: user.id,
		trigger: "rerun",
		promptSnapshot: prompt,
	});
	await runService.setStatus(run.id, "running");
	try {
		await inngest.send({
			name: threadRunEvent,
			data: {
				runId: run.id,
				threadId: id,
				prompt,
				...(parsed.data.modelContextCapChars
					? { modelContextCapChars: parsed.data.modelContextCapChars }
					: {}),
			},
		});
	} catch {
		await runService.setStatus(run.id, "failed");
		return jsonError(502, "RUN_SCHEDULE_FAILED", "Could not schedule the run.");
	}

	return jsonOk({ runId: run.id, threadId: id, dispatched: true });
}

function extractText(content: unknown): string | undefined {
	if (!Array.isArray(content)) {
		return undefined;
	}
	for (const part of content) {
		if (
			typeof part === "object" &&
			part !== null &&
			(part as { type?: string }).type === "text" &&
			typeof (part as { text?: unknown }).text === "string"
		) {
			return (part as { text: string }).text.trim() || undefined;
		}
	}
	return undefined;
}

import { requireUser } from "@aevryn/auth";
