import { createServerSupabaseForNext } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const runService = new RunService();
const threadService = new ThreadService();
const memberService = new MemberService();

const ACTIVE = new Set([
	"pending",
	"running",
	"sleeping",
	"waiting",
	"awaiting_approval",
]);

function jsonError(status: number, code: string, message: string): Response {
	return Response.json(
		{ data: null, error: { code, message, details: null }, meta: {} },
		{ status, headers: { "cache-control": "no-store" } },
	);
}

export async function POST(
	_request: Request,
	ctx: { params: Promise<{ id: string }> },
): Promise<Response> {
	const supabase = await createServerSupabaseForNext();
	let user: { id: string };
	try {
		user = await requireUser(supabase);
	} catch {
		return jsonError(401, "UNAUTHENTICATED", "Sign in first.");
	}
	const { id } = await ctx.params;
	const run = await runService.findById(id);
	if (!run) {
		return jsonError(404, "RUN_NOT_FOUND", "Run does not exist.");
	}
	const thread = await threadService.findById(run.threadId);
	if (!thread) {
		return jsonError(404, "THREAD_NOT_FOUND", "Thread does not exist.");
	}
	const members = await memberService.listByUser(user.id);
	const canAccess =
		thread.userId === user.id ||
		members.some((m) => m.workspaceId === thread.workspaceId);
	if (!canAccess) {
		return jsonError(403, "FORBIDDEN", "You do not have access to this run.");
	}
	if (!ACTIVE.has(run.status)) {
		return Response.json(
			{ data: { runId: run.id, status: run.status }, error: null, meta: {} },
			{ headers: { "cache-control": "no-store" } },
		);
	}
	const updated = await runService.setStatus(run.id, "cancelled");
	return Response.json(
		{
			data: { runId: run.id, status: updated?.status ?? "cancelled" },
			error: null,
			meta: {},
		},
		{ headers: { "cache-control": "no-store" } },
	);
}

