async autoTitle(
	id: string,
	fromMessage: string,
): Promise<Thread | undefined> {
	const trimmed = fromMessage.trim();
	if (!trimmed) {
		return this.findById(id);
	}
	const title =
		trimmed.length > AUTO_TITLE_CHARS
			? `${trimmed.slice(0, AUTO_TITLE_CHARS)}…`
			: trimmed;
	return this.rename(id, title);
}

