import { z } from "zod";

import { requireUser } from "@aevryn/auth";
import { MemberService, ThreadService, WorkflowService } from "@aevryn/workflow";

import { createServerSupabaseForNext } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const threadService = new ThreadService();
const memberService = new MemberService();
const workflowService = new WorkflowService();

function jsonError(status: number, code: string, message: string): Response {
	return Response.json(
		{ data: null, error: { code, message, details: null }, meta: {} },
		{ status, headers: { "cache-control": "no-store" } },
	);
}

const patchSchema = z
	.object({
		title: z.string().min(1).max(200).optional(),
		boundWorkflowId: z.string().min(1).nullable().optional(),
		shareEnabled: z.boolean().optional(),
	})
	.refine(
		(value) =>
			value.title !== undefined ||
			value.boundWorkflowId !== undefined ||
			value.shareEnabled !== undefined,
		{ message: "Nothing to update." },
	);

export async function PATCH(
	request: Request,
	ctx: { params: Promise<{ id: string }> },
): Promise<Response> {
	const supabase = await createServerSupabaseForNext();
	let user: { id: string };
	try {
		user = await requireUser(supabase);
	} catch {
		return jsonError(401, "UNAUTHENTICATED", "Sign in first.");
	}
	const { id } = await ctx.params;
	const thread = await threadService.findById(id);
	if (!thread || thread.deletedAt) {
		return jsonError(404, "THREAD_NOT_FOUND", "Thread does not exist.");
	}
	const members = await memberService.listByUser(user.id);
	const isEditor =
		thread.userId === user.id ||
		members.some(
			(m) => m.workspaceId === thread.workspaceId && m.role !== "viewer",
		);
	if (!isEditor) {
		return jsonError(403, "FORBIDDEN", "You cannot edit this thread.");
	}

	let body: unknown;
	try {
		body = await request.json();
	} catch {
		body = null;
	}
	const parsed = patchSchema.safeParse(body);
	if (!parsed.success) {
		return jsonError(400, "INVALID_PAYLOAD", "Invalid thread update.");
	}

	if (parsed.data.boundWorkflowId !== undefined) {
		if (parsed.data.boundWorkflowId === null) {
			await threadService.unbindWorkflow(id);
		} else {
			const workflow = await workflowService.findById(
				parsed.data.boundWorkflowId,
			);
			if (!workflow || workflow.workspaceId !== thread.workspaceId) {
				return jsonError(404, "WORKFLOW_NOT_FOUND", "Workflow does not exist.");
			}
			await threadService.bindWorkflow(id, parsed.data.boundWorkflowId);
		}
	}
	if (parsed.data.shareEnabled !== undefined) {
		await threadService.setShareEnabled(id, parsed.data.shareEnabled);
	}
	if (parsed.data.title !== undefined) {
		await threadService.rename(id, parsed.data.title.trim());
	}

	const updated = await threadService.findById(id);
	return Response.json(
		{
			data: {
				id,
				title: updated?.title ?? thread.title,
				boundWorkflowId: updated?.boundWorkflowId ?? null,
				shareEnabled: updated?.shareEnabled ?? false,
			},
			error: null,
			meta: {},
		},
		{ headers: { "cache-control": "no-store" } },
	);
}

