import { z } from "zod";

import { requireUser } from "@aevryn/auth";
import { inngest, threadRunEvent } from "@aevryn/inngest";
import {
	ApprovalService,
	MemberService,
	RunService,
	ThreadService,
} from "@aevryn/workflow";

import { createServerSupabaseForNext } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const approvalService = new ApprovalService();
const runService = new RunService();
const threadService = new ThreadService();
const memberService = new MemberService();

function jsonError(status: number, code: string, message: string): Response {
	return Response.json(
		{ data: null, error: { code, message, details: null }, meta: {} },
		{ status, headers: { "cache-control": "no-store" } },
	);
}

const resolveSchema = z.object({
	action: z.enum(["approve", "approve-run", "deny"]),
});

export async function POST(
	request: Request,
	ctx: { params: Promise<{ id: string }> },
): Promise<Response> {
	const supabase = await createServerSupabaseForNext();
	let user: { id: string };
	try {
		user = await requireUser(supabase);
	} catch {
		return jsonError(401, "UNAUTHENTICATED", "Sign in first.");
	}
	const { id } = await ctx.params;

	let body: unknown;
	try {
		body = await request.json();
	} catch {
		body = null;
	}
	const parsed = resolveSchema.safeParse(body);
	if (!parsed.success) {
		return jsonError(400, "INVALID_PAYLOAD", "`action` is required.");
	}

	const approval = await approvalService.findById(id);
	if (!approval) {
		return jsonError(404, "APPROVAL_NOT_FOUND", "Approval does not exist.");
	}
	const run = await runService.findById(approval.runId);
	if (!run) {
		return jsonError(404, "RUN_NOT_FOUND", "Run does not exist.");
	}
	const thread = await threadService.findById(run.threadId);
	if (!thread) {
		return jsonError(404, "THREAD_NOT_FOUND", "Thread does not exist.");
	}
	const members = await memberService.listByUser(user.id);
	const canAccess =
		thread.userId === user.id ||
		members.some((m) => m.workspaceId === thread.workspaceId);
	if (!canAccess) {
		return jsonError(403, "FORBIDDEN", "You do not have access to this approval.");
	}

	const resolved = parsed.data.action === "deny" ? "denied" : "approved";
	await approvalService.resolve(id, resolved);

	if (parsed.data.action === "deny") {
		return Response.json(
			{ data: { approvalId: id, status: "denied" }, error: null, meta: {} },
			{ headers: { "cache-control": "no-store" } },
		);
	}

	// Gather every still-pending approval for this run and count them all as
	// approved so the resumed pass never re-asks for the same tools.
	const pending = await approvalService.listPendingForRun(run.id);
	const approvedTools = new Set<string>([approval.toolName]);
	for (const candidate of pending) {
		if (candidate.status === "pending") {
			await approvalService.markAutoApproved(candidate.id);
			approvedTools.add(candidate.toolName);
		}
	}

	await runService.resumeTriggeredBy(run.id);
	const prompt =
		(typeof run.promptSnapshot === "string" && run.promptSnapshot.trim()
			? run.promptSnapshot
			: await lastUserPrompt(run.threadId)) ?? "";

	try {
		await inngest.send({
			name: threadRunEvent,
			data: {
				runId: run.id,
				threadId: run.threadId,
				prompt,
				approvedToolNames: [...approvedTools],
			},
		});
	} catch {
		return jsonError(502, "RESUME_FAILED", "Approved but could not resume the run.");
	}

	return Response.json(
		{
			data: {
				approvalId: id,
				status: resolved,
				runId: run.id,
				resumed: parsed.data.action === "approve-run" ||
					parsed.data.action === "approve",
			},
			error: null,
			meta: {},
		},
		{ headers: { "cache-control": "no-store" } },
	);
}

async function lastUserPrompt(threadId: string): Promise<string | undefined> {
	const messages = await threadService.listMessagesByThread(threadId);
	const lastUser = [...messages].reverse().find((m) => m.role === "user");
	if (!lastUser) {
		return undefined;
	}
	const content = (lastUser.content ?? []) as Array<{
		type?: string;
		text?: string;
	}>;
	const textPart = content.find((part) => part.type === "text");
	return textPart?.text?.trim() || undefined;
}

import { z } from "zod";

import { requireUser } from "@aevryn/auth";
import { NotificationService } from "@aevryn/workflow";

import { createServerSupabaseForNext } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const notificationService = new NotificationService();

function jsonError(status: number, code: string, message: string): Response {
	return Response.json(
		{ data: null, error: { code, message, details: null }, meta: {} },
		{ status, headers: { "cache-control": "no-store" } },
	);
}

const readSchema = z.object({
	ids: z.array(z.string().min(1)).max(200).optional(),
	all: z.boolean().optional(),
});

export async function POST(request: Request): Promise<Response> {
	const supabase = await createServerSupabaseForNext();
	let user: { id: string };
	try {
		user = await requireUser(supabase);
	} catch {
		return jsonError(401, "UNAUTHENTICATED", "Sign in first.");
	}

	let body: unknown;
	try {
		body = await request.json();
	} catch {
		body = null;
	}
	const parsed = readSchema.safeParse(body);
	if (!parsed.success) {
		return jsonError(400, "INVALID_PAYLOAD", "Invalid read payload.");
	}

	if (parsed.data.all || !parsed.data.ids) {
		await notificationService.markAllRead(user.id);
	} else {
		for (const id of parsed.data.ids) {
			await notificationService.markRead(id, user.id);
		}
	}

	const unread = await notificationService.unreadCount(user.id);
	return Response.json(
		{ data: { unread }, error: null, meta: {} },
		{ headers: { "cache-control": "no-store" } },
	);
}

