import type { SupabaseClient } from "@supabase/supabase-js";

import { getProfileOrCreate } from "@/lib/profile";
import type {
	SerializedGroup,
	SerializedMessage,
	SerializedNotification,
	SerializedRun,
	SerializedRunActivity,
	SerializedThread,
	SerializedWorkspace,
	SerializedWorkflow,
	WorkspaceHydration,
} from "@/types/workspace";

const ACTIVE_STATUSES = new Set([
	"pending",
	"running",
	"sleeping",
	"waiting",
]);

type ThreadRow = {
	id: string;
	title: string;
	group_id: string | null;
	bound_workflow_id: string | null;
	share_enabled: boolean;
	last_message_at: string | null;
	created_at: string;
};

type RunRow = {
	id: string;
	thread_id: string;
	status: string;
	trigger: string;
	created_at: string;
	finished_at: string | null;
	prompt_snapshot: unknown;
};

function threadStatus(run: RunRow | undefined): SerializedThread["status"] {
	if (!run) {
		return "idle";
	}
	if (ACTIVE_STATUSES.has(run.status)) {
		return "active";
	}
	if (run.status === "awaiting_approval") {
		return "awaiting_approval";
	}
	if (run.status === "queued") {
		return "queued";
	}
	return "idle";
}

export async function loadWorkspaceHydration(
	supabase: SupabaseClient,
	user: { id: string; email?: string | null },
	workspaceId: string,
): Promise<WorkspaceHydration> {
	const profile = await getProfileOrCreate(supabase, user.id);

	const [{ data: workspaces }, { data: memberships }] = await Promise.all([
		supabase.from("workspaces").select("id,name,is_default"),
		supabase
			.from("workspace_members")
			.select("workspace_id,role"),
	]);

	const workspaceMap = new Map(
		(workspaces ?? []).map((row) => [row.id, row]),
	);
	const roleByWorkspace = new Map(
		(memberships ?? []).map((row) => [row.workspace_id, row.role]),
	);
	const serializedWorkspaces: SerializedWorkspace[] = (workspaces ?? [])
		.filter((row) => workspaceMap.has(row.id))
		.map((row) => ({
			id: row.id,
			name: row.name,
			isDefault: row.is_default === true,
			role: roleByWorkspace.get(row.id) ?? "viewer",
		}));

	const [{ data: groups }, { data: threads }, { data: notifications }] =
		await Promise.all([
			supabase
				.from("groups")
				.select("id,name,kind,position")
				.eq("workspace_id", workspaceId)
				.order("position", { ascending: true }),
			supabase
				.from("threads")
				.select(
					"id,title,group_id,bound_workflow_id,share_enabled,last_message_at,created_at",
				)
				.eq("workspace_id", workspaceId)
				.order("created_at", { ascending: false }),
			supabase
				.from("notifications")
				.select("id,title,body,type,created_at,read_at")
				.eq("user_id", user.id)
				.order("created_at", { ascending: false })
				.limit(50),
		]);

	const recentRuns = await fetchRunsForThreads(
		supabase,
		(threads ?? []).map((row) => row.id),
	);
	const runsByThreadId = new Map<string, RunRow>();
	for (const run of recentRuns) {
		const existing = runsByThreadId.get(run.thread_id);
		if (!existing || run.created_at > existing.created_at) {
			runsByThreadId.set(run.thread_id, run);
		}
	}

	const threadRows = (threads ?? []) as ThreadRow[];
	const serializedThreads = new Map<string, SerializedThread & { title: string }>();
	for (const row of threadRows) {
		serializedThreads.set(row.id, {
			id: row.id,
			title: row.title,
			status: threadStatus(runsByThreadId.get(row.id)),
			boundWorkflowId: row.bound_workflow_id,
			shareEnabled: row.share_enabled === true,
			lastMessageAt: row.last_message_at,
			createdAt: row.created_at,
		});
	}

	const serializedGroups: Array<SerializedGroup & {
		threads: Array<SerializedThread & { title: string }>;
	}> = (groups ?? [])
		.filter(
			(row): row is (typeof groups)[number] =>
				row.kind === "custom" || row.kind === "system",
		)
		.map((row) => ({
			id: row.id,
			name: row.name,
			kind: row.kind,
			position: row.position,
			locked: row.kind === "system" && row.name.toUpperCase() === "INVITES",
			threadCount: 0,
			threads: [],
		}));

	for (const group of serializedGroups) {
		group.threads = threadRows
			.filter((row) => row.group_id === group.id)
			.map((row) => serializedThreads.get(row.id)!)
			.filter((thread) => thread !== undefined);
		group.threadCount = group.threads.length;
	}

	const serializedNotifications: SerializedNotification[] = (notifications ?? [])
		.slice(0, 50)
		.map((row) => ({
			id: row.id,
			title: row.title,
			body: row.body,
			type: row.type,
			createdAt: row.created_at,
			readAt: row.read_at,
		}));

	const { data: workflows } = await supabase
		.from("workflows")
		.select("id,title,status,auto_approve")
		.eq("workspace_id", workspaceId)
		.order("created_at", { ascending: true });
	const serializedWorkflows: SerializedWorkflow[] = (workflows ?? []).map(
		(row) => ({
			id: row.id,
			title: row.title,
			status: row.status,
			autoApprove: row.auto_approve === true,
		}),
	);

	const activeWorkspace = workspaceMap.get(workspaceId);
	return {
		auth: {
			user: { id: user.id, email: user.email },
			profile: {
				plan: null,
				preferOwnKeysInShared: null,
				onboarded: profile?.onboarded ?? false,
				preAnswers: profile?.preAnswers ?? null,
			},
			workspaces: serializedWorkspaces,
			activeWorkspaceId: workspaceId,
		},
