export async function loadThreadHydration(
	supabase: SupabaseClient,
	user: { id: string },
	threadId: string,
): Promise<{
	thread: {
		id: string;
		title: string;
		groupId: string | null;
		shareEnabled: boolean;
		boundWorkflowId: string | null;
		workspaceId: string;
	};
	messages: SerializedMessage[];
	runs: SerializedRun[];
	activities: SerializedRunActivity[];
	pendingApprovals: SerializedApprovalRequest[];
	isMemberViewer: boolean;
}> {
	const { data: threadRow } = await supabase
		.from("threads")
		.select(
			"id,title,group_id,share_enabled,bound_workflow_id,workspace_id,user_id",
		)
		.eq("id", threadId)
		.single();

	const empty = {
		thread: {
			id: threadId,
			title: "",
			groupId: null,
			shareEnabled: false,
			boundWorkflowId: null,
			workspaceId: "",
		},
		messages: [],
		runs: [],
		activities: [],
		pendingApprovals: [],
		isMemberViewer: false,
	};
	if (!threadRow) {
		return empty;
	}

	const [{ data: messages }, { data: runs }, { data: activities }, { data: approvals }] =
		await Promise.all([
			supabase
				.from("chat_messages")
				.select("id,thread_id,role,status,content,created_at,updated_at")
				.eq("thread_id", threadId)
				.order("created_at", { ascending: true }),
			supabase
				.from("runs")
				.select("id,thread_id,status,trigger,created_at,finished_at,prompt_snapshot")
				.eq("thread_id", threadId)
				.order("created_at", { ascending: false })
				.limit(50),
			supabase
				.from("run_activities")
				.select("id,run_id,type,status,step_label,title,description,detail,created_at")
				.in(
					"run_id",
					(runs ?? []).map((row) => row.id),
				)
				.order("created_at", { ascending: true }),
			supabase
				.from("approval_requests")
				.select("id,run_id,thread_id,workflow_id,tool_name,input,schema,status,auto_approved,created_at")
				.eq("thread_id", threadId)
				.eq("status", "pending")
				.order("created_at", { ascending: false }),
		]);

	return {
		thread: {
			id: threadId,
			title: threadRow.title,
			groupId: threadRow.group_id,
			shareEnabled: threadRow.share_enabled === true,
			boundWorkflowId: threadRow.bound_workflow_id,
			workspaceId: threadRow.workspace_id,
		},
		messages: (messages ?? []).map((row) => ({
			id: row.id,
			threadId: row.thread_id,
			role: row.role as SerializedMessage["role"],
			status: row.status as SerializedMessage["status"],
			content: row.content as SerializedMessage["content"],
			createdAt: row.created_at,
			updatedAt: row.updated_at,
		})),
		runs: (runs ?? []).map((row) => ({
			id: row.id,
			status: row.status as SerializedRun["status"],
			trigger: row.trigger,
			createdAt: row.created_at,
			finishedAt: row.finished_at,
			promptSnapshot: row.prompt_snapshot,
		})),
		activities: (activities ?? []).map((row) => ({
			id: row.id,
			runId: row.run_id,
			type: row.type,
			status: row.status,
			stepLabel: row.step_label,
			title: row.title,
			description: row.description,
			detail: row.detail,
			createdAt: row.created_at,
		})),
		pendingApprovals: (approvals ?? []).map((row) => ({
			id: row.id,
			runId: row.run_id,
			threadId: row.thread_id,
			workflowId: row.workflow_id,
			toolName: row.tool_name,
			input: row.input,
			schema: row.schema,
			status: row.status,
			autoApproved: row.auto_approved === true,
			createdAt: row.created_at,
		})),
		isMemberViewer: threadRow.user_id !== user.id,
	};
}

async function fetchRunsForThreads(
	supabase: SupabaseClient,
	threadIds: string[],
): Promise<RunRow[]> {
	if (threadIds.length === 0) {
		return [];
	}
	const all: RunRow[] = [];
	for (let from = 0; from < threadIds.length; from += 100) {
		const slice = threadIds.slice(from, from + 100);
		if (slice.length === 0) {
			break;
		}
		const { data, error } = await supabase
			.from("runs")
			.select("id,thread_id,status,trigger,created_at,finished_at,prompt_snapshot")
			.in("thread_id", slice)
			.order("created_at", { ascending: false })
			.limit(500);
		if (!error) {
			all.push(...(data ?? []));
		}
	}
	return all;
}

