"use client";

import { useEffect } from "react";

import {
	SidebarInset,
	SidebarProvider,
} from "@aevryn/ui/components/ui/sidebar";

import { useRealtimeNotifications } from "@/hooks/use-realtime-thread";
import { WorkspaceSidebar } from "@/components/workspace/sidebar";
import { useAuthStore } from "@/stores/auth-store";
import { useSidebarStore } from "@/stores/sidebar-store";
import { useThreadStore } from "@/stores/thread-store";
import type { WorkspaceHydration } from "@/types/workspace";

export function WorkspaceClient({
	hydration,
	children,
}: {
	hydration: WorkspaceHydration;
	children: React.ReactNode;
}) {
	const hydrateAuth = useAuthStore((s) => s.hydrate);
	const hydrateGroups = useThreadStore((s) => s.hydrateGroups);
	const hydrateNotifications = useSidebarStore((s) => s.hydrateNotifications);

	useEffect(() => {
		hydrateAuth(hydration.auth);
		hydrateGroups(hydration.groups);
		hydrateNotifications(hydration.notifications);
	}, [hydration, hydrateAuth, hydrateGroups, hydrateNotifications]);

	useRealtimeNotifications(hydration.auth.user.id);

	return (
		<SidebarProvider persistCookie defaultOpen>
			<WorkspaceSidebar />
			<SidebarInset>{children}</SidebarInset>
		</SidebarProvider>
	);
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";

import { Plus, Play, Square, Settings, LogOut, Users } from "lucide-react";

import {
	Sidebar,
	SidebarHeader,
	SidebarContent,
	SidebarFooter,
	SidebarGroup,
	SidebarGroupLabel,
	SidebarGroupActions,
	SidebarGroupAction,
	SidebarMenu,
	SidebarMenuItem,
	SidebarMenuButton,
	SidebarMenuBadge,
	SidebarMenuAction,
	SidebarMenuActions,
} from "@aevryn/ui/components/ui/sidebar";
import { Tooltip } from "@aevryn/ui/components/ui/tooltip";
import { DropdownMenu, DropdownTrigger, DropdownContent } from "@aevryn/ui/components/ui/dropdown";
import { MenuItem } from "@aevryn/ui/components/ui/menu-item";
import { SidebarWorkspaceHeader, WorkspaceTile } from "@aevryn/ui/components/sidebar-app/workspace-header";
import { SidebarUserFooter } from "@aevryn/ui/components/sidebar-app/user-footer";
import { SidebarSearchField } from "@aevryn/ui/components/sidebar-app/search-field";
import { Button } from "@aevryn/ui/components/ui/button";
import { useTheme } from "next-themes";

import { useAuthStore } from "@/stores/auth-store";
import { useThreadStore } from "@/stores/thread-store";
import { useSidebarStore } from "@/stores/sidebar-store";
import { useUiStore } from "@/stores/ui-store";
import { useComposerStore } from "@/stores/composer-store";
import { NotificationsSheet } from "@/components/workspace/notifications-sheet";

const STATUS_DOT: Record<string, string> = {
	running: "bg-emerald-500",
	queued: "bg-amber-500",
	sleeping: "bg-sky-500",
	waiting: "bg-violet-500",
	awaiting_approval: "bg-yellow-500",
	failed: "bg-red-500",
	idle: "bg-muted-foreground/40",
};

export function WorkspaceSidebar() {
	const router = useRouter();
	const activeWorkspaceId = useAuthStore((s) => s.activeWorkspaceId);
	const workspaces = useAuthStore((s) => s.workspaces);
	const groups = useThreadStore((s) => s.groups);
	const activeThreadId = useThreadStore((s) => s.activeThreadId);
	const { search, collapsed, toggleCollapsed } = useSidebarStore();

	const setNotificationsOpen = useUiStore((s) => s.setNotificationsOpen);
	const openRename = useUiStore((s) => s.openRename);

	const { resolvedTheme, setTheme } = useTheme();
	const [notificationsOpen, setNotificationsOpenLocal] = useState(false);
	const toggleNotifications = () => setNotificationsOpenLocal((o) => !o);

	const visibleGroups = useMemo(() => {
		const q = search.trim().toLowerCase();
		const filtered = groups.map((group) => ({
			...group,
			threads: q
				? group.threads.filter((t) => (t.title || "").toLowerCase().includes(q))
				: group.threads,
		}));
		return q ? filtered.filter((g) => g.threads.length > 0) : filtered;
	}, [groups, search]);

	const selectThread = (id: string) => {
		useThreadStore.setState({ activeThreadId: id });
		router.push(`/workspace/${activeWorkspaceId}/${id}`);
	};

	const newThread = async () => {
		if (!activeWorkspaceId) return;
		const res = await fetch("/api/threads", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ workspaceId: activeWorkspaceId }),
		});
		if (!res.ok) return;
		const { data } = (await res.json()) as {
			data: { id: string; title: string; groupId: string | null };
		};
		if (!data?.id) return;
		const firstGroup = groups[0];
		useThreadStore.getState().updateThread(data.id, {
			title: data.title,
			status: "idle",
			boundWorkflowId: null,
			shareEnabled: false,
			lastMessageAt: null,
			createdAt: new Date().toISOString(),
		});
		selectThread(data.id);
	};

	return (
		<>
			<NotificationsSheet
				open={notificationsOpen}
				onOpenChange={setNotificationsOpenLocal}
			/>
			<Sidebar variant="inset" bordered={false}>
				<SidebarHeader>
					<SidebarWorkspaceHeader
						name={
							workspaces.find((w) => w.id === activeWorkspaceId)?.name ?? "Workspace"
						}
						tile={<WorkspaceTile>{(workspaces.find((w) => w.id === activeWorkspaceId)?.name ?? "W").slice(0, 1).toUpperCase()}</WorkspaceTile>}
						checkedIndex={Math.max(
							0,
							workspaces.findIndex((w) => w.id === activeWorkspaceId),
						)}
						menu={
							<>
								{workspaces.map((workspace, index) => (
									<MenuItem
										key={workspace.id}
										index={index}
										label={workspace.name}
										checked={workspace.id === activeWorkspaceId}
										onSelect={() => {
											useAuthStore.setState({ activeWorkspaceId: workspace.id });
											router.push(`/workspace/${workspace.id}`);
										}}
									/>
								))}
								<MenuItem
									index={workspaces.length}
									icon={<Plus className="size-4" />}
									label="New workspace"
									onSelect={() => router.push("/workspace/new")}
								/>
							</>
						}
					/>
					<div className="flex flex-col gap-1">
						<SidebarSearchField value={search} onChange={(v) => useSidebarStore.setState({ search: v })} />
						<SidebarMenu>
							<SidebarMenuItem>
								<SidebarMenuButton
									icon={<Users className="size-4" />}
									onClick={toggleNotifications}
								>
									Notifications
									<SidebarMenuBadge count={useSidebarStore((s) => s.unreadCount)} />
								</SidebarMenuButton>
							</SidebarMenuItem>
							<SidebarMenuItem>
								<SidebarMenuButton icon={<Plus className="size-4" />} onClick={newThread}>
									New
								</SidebarMenuButton>
							</SidebarMenuItem>
							<SidebarMenuItem>
								<SidebarMenuButton icon={<Play className="size-4" />}>
									Run
									<SidebarMenuActions>
										<Tooltip content="Run all workflows" side="top">
											<SidebarMenuAction aria-label="Run all" />
										</Tooltip>
									</SidebarMenuActions>
								</SidebarMenuButton>
							</SidebarMenuItem>
						</SidebarMenu>
					</div>
				</SidebarHeader>

				<SidebarContent>
					{visibleGroups.map((group) => (
						<SidebarGroup
							key={group.id}
							collapsible
							defaultCollapsed={collapsed[group.id] === true}
							onCollapsedChange={(value) => toggleCollapsed(group.id, value)}
						>
							<SidebarGroupLabel>{group.name}</SidebarGroupLabel>
							<SidebarGroupActions>
								<Tooltip content="Run all in group" side="top">
									<SidebarGroupAction aria-label="Run all">
										<Play className="size-3.5" />
									</SidebarGroupAction>
								</Tooltip>
								<DropdownMenu>
									<DropdownTrigger asChild>
										<SidebarGroupAction aria-label="Group actions">
											<Settings className="size-3.5" />
										</SidebarGroupAction>
									</DropdownTrigger>
									<DropdownContent align="end">
										<MenuItem index={0} label="Rename group" />
										<MenuItem index={1} label="Delete group" />
									</DropdownContent>
								</DropdownMenu>
							</SidebarGroupActions>
							<SidebarMenu>
								{group.threads.map((thread) => {
									const active = thread.id === activeThreadId;
									return (
										<SidebarMenuItem key={thread.id}>
											<SidebarMenuButton
												isActive={active}
												onClick={() => selectThread(thread.id)}
											>
												<span
													className={`size-1.5 shrink-0 rounded-full ${STATUS_DOT[thread.status] ?? STATUS_DOT.idle}`}
												/>
												<span className="truncate">{thread.title}</span>
											</SidebarMenuButton>
											<SidebarMenuActions>
												<Tooltip content="Stop" side="top">
													<SidebarMenuAction
														aria-label="Stop"
														onClick={() => {}}
													>
														<Square className="size-3.5" />
													</SidebarMenuAction>
												</Tooltip>
												<Tooltip content="Rename" side="top">
													<SidebarMenuAction
														aria-label="Rename"
														onClick={() => openRename(thread.id)}
													>
														<Settings className="size-3.5" />
													</SidebarMenuAction>
												</Tooltip>
											</SidebarMenuActions>
										</SidebarMenuItem>
									);
								})}
							</SidebarMenu>
						</SidebarGroup>
					))}
				</SidebarContent>

				<SidebarFooter>
					<SidebarUserFooter
						email={useAuthStore((s) => s.user?.email ?? "")}
						userTitle={useAuthStore((s) => s.user?.email ?? "")}
						onThemeToggle={() => setTheme(resolvedTheme === "dark" ? "light" : "dark")}
						onSettings={() => useUiStore.getState().setSettingsOpen(true)}
						onSignOut={() => {
							window.location.href = "/api/auth/logout";
						}}
					/>

					{visibleGroups.filter((g) => g.locked).map((group) => (
						<div
							key={`invite-${group.id}`}
							className="m-2 flex items-center gap-2 rounded-lg border border-dashed px-3 py-2 text-xs text-muted-foreground"
						>
							<Plus className="size-3.5" />
							<span>Invite someone to {group.name}</span>
						</div>
					))}
				</SidebarFooter>
			</Sidebar>
		</>
	);
}

