"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";

import { Plus, Play, Square, Settings, Users, User, Moon, Sun } from "lucide-react";

import {
	Sidebar,
	SidebarHeader,
	SidebarContent,
	SidebarFooter,
	SidebarGroup,
	SidebarGroupLabel,
	SidebarGroupActions,
	SidebarGroupAction,
	SidebarMenu,
	SidebarMenuItem,
	SidebarMenuButton,
	SidebarMenuBadge,
	SidebarMenuAction,
} from "@aevryn/ui/components/ui/sidebar";
import { Tooltip } from "@aevryn/ui/components/ui/tooltip";
import {
	DropdownMenu,
	DropdownTrigger,
	DropdownContent,
} from "@aevryn/ui/components/ui/dropdown";
import { MenuItem } from "@aevryn/ui/components/ui/menu-item";
import {
	SidebarWorkspaceHeader,
	WorkspaceTile,
} from "@aevryn/ui/components/sidebar-app/workspace-header";
import { SidebarUserFooter } from "@aevryn/ui/components/sidebar-app/user-footer";
import { SidebarSearchField } from "@aevryn/ui/components/sidebar-app/search-field";
import { useTheme } from "next-themes";

import { useAuthStore } from "@/stores/auth-store";
import { useThreadStore } from "@/stores/thread-store";
import { useSidebarStore } from "@/stores/sidebar-store";
import { useUiStore } from "@/stores/ui-store";
import { StopThreadButton } from "@/components/workspace/stop-thread-button";
import { NotificationsSheet } from "@/components/workspace/notifications-sheet";

const STATUS_DOT: Record<string, string> = {
	running: "bg-emerald-500",
	queued: "bg-amber-500",
	sleeping: "bg-sky-500",
	waiting: "bg-violet-500",
	awaiting_approval: "bg-yellow-500",
	failed: "bg-red-500",
	idle: "bg-muted-foreground/40",
};

export function WorkspaceSidebar() {
	const router = useRouter();
	const activeWorkspaceId = useAuthStore((s) => s.activeWorkspaceId);
	const workspaces = useAuthStore((s) => s.workspaces);
	const email = useAuthStore((s) => s.user?.email ?? "");
	const groups = useThreadStore((s) => s.groups);
	const activeThreadId = useThreadStore((s) => s.activeThreadId);
	const threads = useThreadStore((s) => s.threads);
	const runsByThread = useThreadStore((s) => s.runsByThread);
	const search = useSidebarStore((s) => s.search);
	const collapsed = useSidebarStore((s) => s.collapsed);
	const unreadCount = useSidebarStore((s) => s.unreadCount);
	const openRename = useUiStore((s) => s.openRename);
	const setSettingsOpen = useUiStore((s) => s.setSettingsOpen);

	const { resolvedTheme } = useTheme();
	const [notificationsOpen, setNotificationsOpen] = useState(false);

	const latestStatus = useMemo(() => {
		const map = new Map<string, string>();
		for (const [id, runs] of Object.entries(runsByThread)) {
			const run = runs[0];
			if (run) {
				map.set(id, run.status);
			}
		}
		return map;
	}, [runsByThread]);

	const visibleGroups = useMemo(() => {
		const q = search.trim().toLowerCase();
		const filtered = groups
			.map((group) => ({
				...group,
				threads: q
					? group.threads.filter((t) =>
							(t.title || "").toLowerCase().includes(q),
						)
					: group.threads,
			}))
			.map((group) => ({
				...group,
				threads: group.threads
					.map((t) => threads[t.id] ?? t)
					.map((t) => ({
						...t,
						status: (latestStatus.get(t.id) ?? t.status) as WorkspaceThreadStatus,
					})),
			}));
		return q ? filtered.filter((g) => g.threads.length > 0) : filtered;
	}, [groups, threads, runsByThread, search]);

	const selectThread = (id: string) => {
		useThreadStore.setState({ activeThreadId: id });
		router.push(`/workspace/${activeWorkspaceId}/${id}`);
	};

	const createThread = async () => {
		if (!activeWorkspaceId) {
			return;
		}
		const res = await fetch("/api/threads", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ workspaceId: activeWorkspaceId }),
		});
		if (!res.ok) {
			return;
		}
		const json = (await res.json()) as {
			data: { thread: { id: string; title: string; groupId: string | null }; workspaceId: string } | null;
		};
		const thread = json.data?.thread;
		if (!thread) {
			return;
		}
		useThreadStore.getState().updateThread(thread.id, {
			title: thread.title,
			status: "idle",
			boundWorkflowId: null,
			shareEnabled: false,
			lastMessageAt: null,
			createdAt: new Date().toISOString(),
		});
		selectThread(thread.id);
	};

	return (
		<>
			<NotificationsSheet
				open={notificationsOpen}
				onOpenChange={setNotificationsOpen}
			/>
			<Sidebar variant="inset" bordered={false}>
				<SidebarHeader>
					<SidebarWorkspaceHeader
						name={
							workspaces.find((w) => w.id === activeWorkspaceId)?.name ??
							"Workspace"
						}
						tile={
							<WorkspaceTile>
								{(workspaces.find((w) => w.id === activeWorkspaceId)?.name ??
									"W"
								).slice(0, 1).toUpperCase()}
							</WorkspaceTile>
						}
						checkedIndex={Math.max(
							0,
							workspaces.findIndex((w) => w.id === activeWorkspaceId),
						)}
						menu={
							<>
								{workspaces.map((workspace, index) => (
									<MenuItem
										key={workspace.id}
										index={index}
										label={workspace.name}
										checked={workspace.id === activeWorkspaceId}
										onSelect={() => {
											useAuthStore.setState({ activeWorkspaceId: workspace.id });
											router.push(`/workspace/${workspace.id}`);
										}}
									/>
								))}
								<MenuItem
									index={workspaces.length}
									icon={Plus}
									label="New workspace"
									onSelect={() => router.push("/workspace/new")}
								/>
							</>
						}
					/>
					<div className="flex flex-col gap-1">
						<SidebarSearchField
							value={search}
							onChange={(event) =>
								useSidebarStore.setState({ search: event.target.value })
							}
						/>
						<SidebarMenu>
							<SidebarMenuItem>
								<SidebarMenuButton
									icon={Users}
									onClick={() => setNotificationsOpen(true)}
								>
									Notifications
									{unreadCount > 0 && (
										<SidebarMenuBadge>{unreadCount}</SidebarMenuBadge>
									)}
								</SidebarMenuButton>
							</SidebarMenuItem>
							<SidebarMenuItem>
								<SidebarMenuButton
									icon={Plus}
									onClick={createThread}
								>
									New
								</SidebarMenuButton>
							</SidebarMenuItem>
							<SidebarMenuItem>
								<SidebarMenuButton icon={Play}>
									Run all
								</SidebarMenuButton>
							</SidebarMenuItem>
						</SidebarMenu>
					</div>
				</SidebarHeader>

				<SidebarContent>
					{visibleGroups.map((group, groupIndex) => (
						<SidebarGroup
							key={group.id}
							collapsible
							defaultOpen={collapsed[group.id] !== true}
							onOpenChange={(open) =>
								useSidebarStore.setState({ collapsed: { ...collapsed, [group.id]: !open } })
							}
						>
							<SidebarGroupLabel>{group.name}</SidebarGroupLabel>
							<SidebarGroupActions>
								<Tooltip content="Run all in group" side="top">
									<SidebarGroupAction aria-label="Run all in group">
										<Play className="size-3.5" />
									</SidebarGroupAction>
								</Tooltip>
								{!group.locked && (
									<DropdownMenu>
										<DropdownTrigger
											render={
												<SidebarGroupAction aria-label="Group actions">
													<Settings className="size-3.5" />
												</SidebarGroupAction>
											}
										/>
										<DropdownContent align="end" checkedIndex={groupIndex}>
											<MenuItem index={0} label="Rename group" />
											<MenuItem index={1} label="Delete group" />
										</DropdownContent>
									</DropdownMenu>
								)}
							</SidebarGroupActions>
							<SidebarMenu>
								{group.threads.map((thread) => (
									<SidebarMenuItem key={thread.id}>
										<SidebarMenuButton
											isActive={thread.id === activeThreadId}
											onClick={() => selectThread(thread.id)}
										>
											<span
												className={`size-1.5 shrink-0 rounded-full ${STATUS_DOT[thread.status] ?? STATUS_DOT.idle}`}
											/>
											<span className="truncate">{thread.title}</span>
										</SidebarMenuButton>
										<SidebarMenuActionsInner
											threadId={thread.id}
											status={thread.status}
											onRename={() => openRename(thread.id)}
											paused={false}
										/>
									</SidebarMenuItem>
								))}
							</SidebarMenu>
						</SidebarGroup>
					))}
				</SidebarContent>

				<SidebarFooter>
					<SidebarUserFooter
						className="min-w-0 flex-1"
						name={email.split("@")[0] || "Guest"}
						avatar={
							<span className="flex size-5 items-center justify-center rounded-full bg-accent text-[10px] font-medium text-accent-foreground">
								{email.slice(0, 1).toUpperCase() || "G"}
							</span>
						}
						menu={
							<>
								<MenuItem
									index={0}
									icon={User}
									label="Account settings"
									onSelect={() => setSettingsOpen(true, "account")}
								/>
								<MenuItem
									index={1}
									icon={Moon}
									label="Appearance"
									onSelect={() =>
										useUiStore.getState().setSettingsSection("appearance")
									}
								/>
							</>
						}
					/>
					<div className="flex items-center gap-1 px-3 py-2"></div>
				</SidebarFooter>
			</Sidebar>
		</>
	);
}

type WorkspaceThreadStatus =
	| "active"
	| "queued"
	| "idle"
	| "awaiting_approval";

function SidebarMenuActionsInner({
	threadId,
	status,
	onRename,
	paused,
}: {
	threadId: string;
	status: WorkspaceThreadStatus;
	onRename: () => void;
	paused: boolean;
}) {
	const active = status === "active" || status === "awaiting_approval";
	return (
		<span className="flex items-center">
			{active && (
				<Tooltip content="Stop" side="top">
					<StopThreadButton threadId={threadId} />
				</Tooltip>
			)}
			{!paused && (
				<Tooltip content="Rename" side="top">
					<SidebarMenuAction aria-label="Rename" onClick={onRename}>
						<Settings className="size-3.5" />
					</SidebarMenuAction>
				</Tooltip>
			)}
		</span>
	);
}

"use client";

import { useState } from "react";
import { Square, Loader } from "lucide-react";

import { useThreadStore } from "@/stores/thread-store";

export function StopThreadButton({ threadId }: { threadId: string }) {
	const [busy, setBusy] = useState(false);
	const runId = useThreadStore((s) => s.runsByThread[threadId]?.[0]?.id);

	const stop = async () => {
		if (!runId || busy) {
			return;
		}
		setBusy(true);
		try {
			await fetch(`/api/runs/${runId}/stop`, { method: "POST" });
		} finally {
			setBusy(false);
		}
	};

	return (
		<button
			aria-label="Stop"
			onClick={stop}
			className="flex h-5 w-5 items-center justify-center outline-none"
		>
			{busy ? (
				<Loader className="size-3.5 animate-spin" />
			) : (
				<Square className="size-3.5" />
			)}
		</button>
	);
}

"use client";

import {
	Dialog,
	DialogContent,
	DialogHeader,
	DialogTitle,
	DialogFooter,
} from "@aevryn/ui/components/ui/dialog";
import { ScrollArea } from "@aevryn/ui/components/ui/scroll-area";
import { Button } from "@aevryn/ui/components/ui/button";
import { Check } from "lucide-react";

import { useSidebarStore } from "@/stores/sidebar-store";

export function NotificationsSheet({
	open,
	onOpenChange,
}: {
	open: boolean;
	onOpenChange: (open: boolean) => void;
}) {
	const notifications = useSidebarStore((s) => s.notifications);
	const markRead = useSidebarStore((s) => s.markRead);
	const unread = notifications.filter((n) => n.readAt === null);

	const markAll = async () => {
		await fetch("/api/notifications/read", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ all: true }),
		});
		useSidebarStore.getState().markAllRead();
	};

	const markOne = async (id: string) => {
		await fetch("/api/notifications/read", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ ids: [id] }),
		});
		markRead(id);
	};

	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogContent className="max-w-md">
				<DialogHeader>
					<DialogTitle>Notifications</DialogTitle>
				</DialogHeader>
				<ScrollArea className="max-h-[60vh]">
					<div className="flex flex-col gap-2">
						{notifications.length === 0 && (
							<p className="p-4 text-sm text-muted-foreground">
								You&apos;re all caught up.
							</p>
						)}
						{notifications.map((notification) => (
							<button
								key={notification.id}
								onClick={() => markOne(notification.id)}
								className="flex items-start gap-2 rounded-lg p-2 text-left text-sm hover:bg-accent"
							>
								<div className="min-w-0 flex-1">
									<p className="font-medium">{notification.title}</p>
									{notification.body && (
										<p className="text-muted-foreground">
											{notification.body}
										</p>
									)}
									<p className="text-[11px] text-muted-foreground">
										{new Date(notification.createdAt).toLocaleString()}
									</p>
								</div>
								{notification.readAt === null && (
									<span className="mt-1 size-2 shrink-0 rounded-full bg-accent" />
								)}
							</button>
						))}
					</div>
				</ScrollArea>
				<DialogFooter>
					<Button
						disabled={unread.length === 0}
						onClick={markAll}
					>
						<Check className="size-4" />
						Mark all read
					</Button>
				</DialogFooter>
			</DialogContent>
		</Dialog>
	);
}

