	DialogHeader,
	DialogTitle,
	DialogDescription,
	DialogClose,
} from "@aevryn/ui/components/ui/dialog";
import { InputGroup, InputField } from "@aevryn/ui/components/ui/input-group";

import { useThreadStore } from "@/stores/thread-store";
import { useAuthStore } from "@/stores/auth-store";
import { useUiStore } from "@/stores/ui-store";

export function WorkspaceHeader({ threadId }: { threadId: string }) {
	const thread = useThreadStore((s) => s.threads[threadId]);
	const workflows = useThreadStore((s) => s.workflows);
	const setThreadStatus = useThreadStore((s) => s.setThreadStatus);
	const updateThread = useThreadStore((s) => s.updateThread);
	const setNotificationsOpen = useUiStore((s) => s.setNotificationsOpen);
	const activeWorkspaceId = useAuthStore((s) => s.activeWorkspaceId);

	const [renameOpen, setRenameOpen] = useState(false);
	const [renameValue, setRenameValue] = useState("");
	const [busy, setBusy] = useState(false);

	if (!thread) {
		return <SidebarInsetTopbar />;
	}

	const isActive = thread.status === "active" || thread.status === "awaiting_approval";

	const run = async () => {
		if (busy || isActive) {
			return;
		}
		setBusy(true);
		try {
			const res = await fetch(`/api/threads/${threadId}/run`, { method: "POST" });
			if (res.ok) {
				setThreadStatus(threadId, "active");
			}
		} finally {
			setBusy(false);
		}
	};

	const stop = async () => {
		const run = useThreadStore.getState().runsByThread[threadId]?.[0];
		if (!run || busy) {
			return;
		}
		setBusy(true);
		try {
			await fetch(`/api/runs/${run.id}/stop`, { method: "POST" });
		} finally {
			setBusy(false);
		}
	};

	const bindWorkflow = async (workflowId: string | null) => {
		await fetch(`/api/threads/${threadId}`, {
			method: "PATCH",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ boundWorkflowId: workflowId }),
		});
		updateThread(threadId, { boundWorkflowId: workflowId });
	};

	const toggleShare = async () => {
		const next = !thread.shareEnabled;
		await fetch(`/api/threads/${threadId}`, {
			method: "PATCH",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ shareEnabled: next }),
		});
		updateThread(threadId, { shareEnabled: next });
	};

	const submitRename = async () => {
		const title = renameValue.trim();
		if (!title) {
			setRenameOpen(false);
			return;
		}
		await fetch(`/api/threads/${threadId}`, {
			method: "PATCH",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ title }),
		});
		updateThread(threadId, { title });
		setRenameOpen(false);
	};

	const boundWorkflow = workflows.find((w) => w.id === thread.boundWorkflowId);

	return (
		<SidebarInsetTopbar className="flex flex-1 items-center justify-between gap-2">
			<Dialog open={renameOpen} onOpenChange={setRenameOpen}>
				<DialogContent size="lg">
					<DialogHeader>
						<DialogTitle>Rename thread</DialogTitle>
						<DialogDescription>Give this thread a new name.</DialogDescription>
					</DialogHeader>
					<InputGroup className="w-full max-w-full">
						<InputField
							index={0}
							label=""
							placeholder="Thread name"
							value={renameValue}
							onChange={setRenameValue}
						/>
					</InputGroup>
					<DialogFooter>
						<DialogClose render={<Button variant="ghost">Cancel</Button>} />
						<Button onClick={submitRename}>Rename</Button>
					</DialogFooter>
				</DialogContent>
