"use client";

import { useEffect, useMemo } from "react";
import { useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
	ChatMessage,
} from "@aevryn/ui/components/ui/chat-message";
import {
	InputMessage,
	type QueuedMessage,
} from "@aevryn/ui/components/ui/input-message";
import { QueuedStack } from "@aevryn/ui/components/queued-stack";
import { SystemMessage } from "@aevryn/ui/components/ui/system-message";
import { ScrollArea } from "@aevryn/ui/components/ui/scroll-area";
import { Crown, Download } from "lucide-react";

import { useThreadChat } from "@/hooks/use-thread-chat";
import { useComposerStore } from "@/stores/composer-store";
import { useThreadStore } from "@/stores/thread-store";
import { ApprovalDialog } from "@/components/workspace/approval-dialog";

function textOf(parts: Array<{ type: string; text?: string }> | undefined): string {
	if (!Array.isArray(parts)) {
		return "";
	}
	return parts
		.filter(
			(part): part is { type: "text"; text: string } =>
				part.type === "text" && typeof part.text === "string",
		)
		.map((part) => part.text)
		.join("");
}

export function ThreadTranscript({
	threadId,
	messages,
	streamingText,
}: {
	threadId: string;
	messages: Array<{
		id: string;
		role: "user" | "assistant";
		status: string;
		content: unknown;
		createdAt: string;
	}>;
	streamingText: string;
}) {
	return (
		<div className="mx-auto flex w-full max-w-3xl flex-1 flex-col justify-end px-4 pb-4">
			<div className="flex flex-col gap-4">
				{/* ephemeral streaming bubble */}
				{(streamingText || messages.length === 0) && (
					<ChatMessage from="assistant">
						{streamingText || "\u200b"}
					</ChatMessage>
				)}

				{messages.map((message) => {
					const text = textOf(message.content as Array<{ type: string; text?: string }>);
					if (!text.trim() && message.status !== "completed" && message.status !== "interrupted") {
						return null;
					}
					return (
						<ChatMessage
							key={message.id}
							from={message.role}
							time={new Date(message.createdAt).toLocaleString()}
						>
							{text}
						</ChatMessage>
					);
				})}
			</div>
		</div>
	);
}

export function ChatView({ threadId }: { threadId: string }) {
	const chat = useThreadChat(threadId);
	const storeMessages = useThreadStore((s) => s.messagesByThread[threadId] ?? []);
	const activeThreadId = useThreadStore((s) => s.activeThreadId);
	const runsByThread = useThreadStore((s) => s.runsByThread[threadId] ?? []);
	const approvals = useThreadStore((s) => s.approvalsByThread[threadId] ?? []);

	const composer = useComposerStore();
	const defaultQueueText = "";
	const draft = composer.value;

	// Mirror queue: composer items from store.
	const queue: QueuedMessage[] = useMemo(
		() =>
			composer.queue.map((item) => ({
				id: item.id,
				text: item.text,
				files: [],
			})),
		[composer.queue],
	);

	const messages = useMemo(() => {
		// canonical rows + locally optimised bubble. conversation from go
		return storeMessages.filter(
			(m) => m.role === "user" || m.status === "completed" || m.status === "interrupted",
		) as Array<{
			id: string;
			role: "user" | "assistant";
			status: string;
			content: unknown;
			createdAt: string;
		}>;
	}, [storeMessages]);

	const handleSend = async (value: string, _files: File[]) => {
		await chat.send(value);
	};

	const handleRemove = async (item: QueuedMessage) => {
		await fetch(`/api/queue/${item.id}`, { method: "DELETE" });
		useComposerStore.getState().removeQueued(item.id);
	};

	const handleEdit = (item: QueuedMessage) => {
		useComposerStore.getState().editQueued(item.id, item.text);
	};

	const handleQueueChange = async (next: QueuedMessage[]) => {
		useComposerStore.getState().setQueue(
			next.map((item) => ({
				id: item.id,
				text: item.text,
				files: [],
				status: "queued" as const,
			})),
		);
		await fetch("/api/queue/reorder", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({
				threadId,
				orderedIds: next.map((item) => item.id),
			}),
		});
	};

	// Auto-scroll to bottom on new messages / streaming text / runs
	const bottomRef = useRef<HTMLDivElement | null>(null);
	useEffect(() => {
		bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
	}, [messages.length, chat.streamingText, runsByThread.length]);

	return (
		<div className="flex min-h-0 flex-1 flex-col">
			<ScrollArea className="min-h-0 flex-1">
				<ThreadTranscript
					threadId={threadId}
					messages={messages}
					streamingText={chat.streamingText}
				/>
				<div ref={bottomRef} />
			</ScrollArea>

			{/* Pending approvals banner */}
			{approvals.length > 0 && (
				<div className="mx-auto w-full max-w-3xl px-4 pb-2">
					<ApprovalDialog threadId={threadId} approvals={approvals} />
				</div>
			)}

			{/* Errors */}
			{chat.error && (
				<div className="mx-auto w-full max-w-3xl px-4 pb-2">
					<SystemMessage variant="error" cta={{ label: "Dismiss", onClick: chat.dismissError }}>
						{chat.error}
					</SystemMessage>
				</div>
			)}

			{/* Queue stack */}
			{queue.length > 0 && (
				<div className="relative mx-auto w-full max-w-3xl px-4">
					<QueuedStack
						queue={queue}
						onQueueChange={handleQueueChange}
						onEdit={handleEdit}
						onRemove={handleRemove}
						bottom={108}
					/>
				</div>
			)}

			{/* Composer */}
			<div className="mx-auto w-full max-w-3xl px-4 pb-4 pt-1">
				<InputMessage
					value={draft}
					onValueChange={useComposerStore.getState().setValue}
					onSend={handleSend}
					status={chat.status}
					onStop={chat.stop}
					placeholder="Ask aevryn anything…"
					rightSlot={({ openFilePicker }) => (
						<button
							type="button"
							onClick={openFilePicker}
							aria-label="Attach files"
							className="flex items-center rounded-md p-1 text-muted-foreground hover:text-foreground"
						>
							<Crown className="size-4" />
						</button>
					)}
				/>
				<div className="mt-1 flex items-center justify-end px-1 text-[11px] text-muted-foreground">
					<span className="inline-flex items-center gap-1">
						<Download className="size-3" />
						{composer.quality >= 8192 ? "Max" : `${Math.round(composer.quality / 1024)}k tokens`}
					</span>
				</div>
			</div>
		</div>
	);
}

