"use client";

import { useState } from "react";
import { Play, ShieldCheck, X, Pencil } from "lucide-react";

import { SystemMessage } from "@aevryn/ui/components/ui/system-message";
import { Button } from "@aevryn/ui/components/ui/button";
import { Tooltip } from "@aevryn/ui/components/ui/tooltip";

import { useThreadStore } from "@/stores/thread-store";
import type { SerializedApprovalRequest } from "@/types/workspace";

const APPROVE_MODES = ["approve", "approve-run", "deny"] as const;
type ApprovalAction = (typeof APPROVE_MODES)[number];

export function ApprovalDialog({
	threadId,
	approvals,
}: {
	threadId: string;
	approvals: SerializedApprovalRequest[];
}) {
	const [busyAction, setBusyAction] = useState<ApprovalAction | null>(null);
	const updateApprovalStatus = useThreadStore(
		(s) => s.updateApprovalStatus,
	);
	const removeApproval = (id: string) => {
		const current = useThreadStore.getState().approvalsByThread[threadId] ?? [];
		const next = current.filter((approval) => approval.id !== id);
		useThreadStore.setState({
			approvalsByThread: {
				...useThreadStore.getState().approvalsByThread,
				[threadId]: next,
			},
		});
	};

	const target = approvals[0];

	const act = async (action: ApprovalAction) => {
		if (!target || busyAction) {
			return;
		}
		setBusyAction(action);
		try {
			const response = await fetch(`/api/approvals/${target.id}`, {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ action }),
			});
			if (response.ok) {
				updateApprovalStatus(
					threadId,
					target.id,
					action === "deny" ? "denied" : "approved",
				);
				removeApproval(target.id);
			}
		} finally {
			setBusyAction(null);
		}
	};

	if (!target) {
		return null;
	}

	const summary = summarizeInput(target.toolName, target.input);

	return (
		<SystemMessage
			variant="warning"
			cta={{ label: "Review & approve", onClick: () => act("approve") }}
		>
			<span className="flex items-center gap-1 font-medium">
				<ShieldCheck className="size-4" />
				{target.toolName}
			</span>
			{summary && <span className="text-muted-foreground">{summary}</span>}
			<span className="mt-2 flex flex-wrap items-center gap-1.5">
				<Tooltip content="Approve and resume the run now" side="top">
					<Button
						size="compact"
						onClick={() => act("approve-run")}
						disabled={busyAction !== null}
					>
						{target.status === "approved" && <Play className="size-3.5" />}
						Approve+Run
					</Button>
				</Tooltip>
				<Tooltip content="Approve, you will start it manually" side="top">
					<Button
						size="compact"
						variant="secondary"
						onClick={() => act("approve")}
						disabled={busyAction !== null}
					>
						Approve
					</Button>
				</Tooltip>
				<Tooltip content="Deny this tool call" side="top">
					<Button
						size="compact"
						variant="tertiary"
						onClick={() => act("deny")}
						disabled={busyAction !== null}
					>
						<X className="size-3.5" />
						Decline
					</Button>
				</Tooltip>
			</span>
		</SystemMessage>
	);
}

function summarizeInput(toolName: string, input: unknown): string {
	if (input == null) {
		return "";
	}
	if (typeof input === "string") {
		return input.length > 140 ? `${input.slice(0, 140)}…` : input;
	}
	if (Array.isArray(input)) {
		return `${input.length} item${input.length === 1 ? "" : "s"}`;
	}
	if (typeof input === "object") {
		const record = input as Record<string, unknown>;
		const preview = Object.entries(record)
			.slice(0, 2)
			.map(([key, value]) => {
				const text =
					typeof value === "string"
						? value.length > 40
							? `${value.slice(0, 40)}…`
							: value
						: JSON.stringify(value) ?? "";
				return `${key}: ${text}`;
			})
			.join(" · ");
		return preview.length > 140 ? `${preview.slice(0, 140)}…` : preview;
	}
	return `${toolName} input pending review`;
}

"use client";

import { useEffect, useMemo } from "react";

import { useRealtimeThread } from "@/hooks/use-realtime-thread";
import { WorkspaceHeader } from "@/components/workspace/header";
import { ChatView } from "@/components/workspace/chat-view";
import { useThreadStore } from "@/stores/thread-store";
import type {
	SerializedApprovalRequest,
	SerializedMessage,
	SerializedRun,
	SerializedRunActivity,
} from "@/types/workspace";

export function ThreadClient({
	threadId,
	data,
}: {
	threadId: string;
	data: {
		thread: {
			id: string;
			title: string;
			groupId: string | null;
			shareEnabled: boolean;
			boundWorkflowId: string | null;
			workspaceId: string;
		};
		messages: SerializedMessage[];
		runs: SerializedRun[];
		activities: SerializedRunActivity[];
		pendingApprovals: SerializedApprovalRequest[];
		isMemberViewer: boolean;
	};
}) {
	useRealtimeThread(threadId);

	const setMessages = useThreadStore((s) => s.setMessages);
	const setRuns = useThreadStore((s) => s.setRuns);
	const upsertActivity = useThreadStore((s) => s.upsertActivity);
	const upsertApproval = useThreadStore((s) => s.upsertApproval);
	const updateThread = useThreadStore((s) => s.updateThread);

	const dataKey = useMemo(
		() => `${data.thread.id}:${data.messages.length}:${data.runs.length}`,
		[data.thread.id, data.messages.length, data.runs.length],
	);

	useEffect(() => {
		useThreadStore.setState({ activeThreadId: threadId });
		setMessages(threadId, data.messages);
		setRuns(threadId, data.runs);
		for (const activity of data.activities) {
			upsertActivity(threadId, activity);
		}
		for (const approval of data.pendingApprovals) {
			upsertApproval(threadId, approval);
		}
		updateThread(threadId, {
			title: data.thread.title,
			boundWorkflowId: data.thread.boundWorkflowId,
			shareEnabled: data.thread.shareEnabled,
			status: data.runs[0]?.status === "awaiting_approval"
				? "awaiting_approval"
				: data.runs[0] &&
						["pending", "running", "sleeping", "waiting"].includes(
							data.runs[0].status,
						)
					? "active"
					: "idle",
		});
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [threadId, dataKey]);

	return (
		<div className="flex min-h-0 flex-1 flex-col">
			<WorkspaceHeader threadId={threadId} />
			<ChatView threadId={threadId} />
		</div>
	);
}

