import { redirect } from "next/navigation";

import { requireUser } from "@aevryn/auth";

import { WorkspaceClient } from "@/components/workspace/workspace-client";
import { createServerSupabaseForNext } from "@/lib/supabase-server";
import { loadWorkspaceHydration } from "@/lib/workspace-data";

export default async function WorkspaceLayout({
	children,
	params,
}: {
	children: React.ReactNode;
	params: Promise<{ workspaceId: string }>;
}) {
	const { workspaceId } = await params;
	const supabase = await createServerSupabaseForNext();

	let user: { id: string; email?: string | null };
	try {
		user = await requireUser(supabase);
	} catch {
		redirect("/");
	}

	const hydration = await loadWorkspaceHydration(supabase, user, workspaceId);

	return (
		<WorkspaceClient hydration={hydration}>{children}</WorkspaceClient>
	);
}

import { redirect } from "next/navigation";

import { Button } from "@aevryn/ui/components/ui/button";
