export default async function WorkspaceHomePage({
	params,
}: {
	params: Promise<{ workspaceId: string }>;
}) {
	const { workspaceId } = await params;
	const supabase = await createServerSupabaseForNext();

	let user: { id: string; email?: string | null };
	try {
		user = await requireUser(supabase);
	} catch {
		redirect("/");
	}

	const hydration = await loadWorkspaceHydration(supabase, user, workspaceId);
	const firstThread = hydration.groups.flatMap((group) => group.threads)[0];

	if (firstThread) {
		redirect(`/workspace/${workspaceId}/${firstThread.id}`);
	}

	return (
		<div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 p-8 text-center">
			<h2 className="text-lg font-medium text-foreground">
				{hydration.workspace.name}
			</h2>
			<p className="max-w-sm text-sm text-muted-foreground">
				No threads yet. Create one and aevryn will start piping live run data
				into this workspace.
			</p>
			<Button>
				<Plus className="size-4" />
				New thread
			</Button>
		</div>
	);
}

import { redirect } from "next/navigation";
import { notFound } from "next/navigation";

import { requireUser } from "@aevryn/auth";

import { createServerSupabaseForNext } from "@/lib/supabase-server";
import { loadThreadHydration } from "@/lib/workspace-data";
import { ThreadClient } from "@/components/workspace/thread-client";

export const metadata = {
	title: "Thread — Aevryn",
};

export default async function ThreadPage({
	params,
}: {
	params: Promise<{ workspaceId: string; threadId: string }>;
}) {
	const { workspaceId, threadId } = await params;
	const supabase = await createServerSupabaseForNext();

	let user: { id: string; email?: string | null };
	try {
		user = await requireUser(supabase);
	} catch {
		redirect("/");
	}

	const threadData = await loadThreadHydration(supabase, user.id, threadId);
	if (!threadData.thread.workspaceId) {
		notFound();
	}
	if (threadData.thread.workspaceId !== workspaceId) {
		redirect(`/workspace/${threadData.thread.workspaceId}/${threadId}`);
	}

	return <ThreadClient threadId={threadId} data={threadData} />;
}

